INSERT INTO `ai_literacy_item` VALUES (3001, 'AI_COGNITION', 'PRIMARY', 4, 6, '理解生成式AI可以生成有用信息，但输出并不天然等于事实。', 2002, 'DEMO：用于支持学生形成对AI能力与局限的基础认识。', 'ailit_demo_3001');
