INSERT INTO `course_project` VALUES (1012, 1, 'aa', 'aa', 'NEW_TOPIC', 2, 1, 'GENERAL', 'GROUP', '[\"TABLET\"]', '[\"LIMITED_TIME\"]', '暂无', 'PEDAGOGY_PENDING', '[\"OBJECTIVE\", \"PEDAGOGY\", \"QUALITY\", \"ARTIFACT\"]', '2026-09-06 18:27:26', '2026-09-08 21:11:48', '2026-09-08 21:11:48', '没有', 42, 40, '{\"constraints\": [\"课时仅40分钟，时间紧张。\", \"班级人数较多，组织管理与个别指导压力大。\", \"学生零基础，起点水平不明确。\", \"“aa”主题未界定，备课资源与方向不足。\", \"仅有平板可用，且未必能有效用于全员同步练习。\"], \"coreProblem\": \"课题/话题“aa”过于模糊，缺少明确的学习对象和范围，难以设计聚焦的课堂活动与评估。\", \"existingFoundation\": \"几乎没有与“aa”相关的已知先备知识或学习经历。\", \"learningDifficulties\": [\"因主题不明确，学生难以建立学习目标与意义感，注意力易分散。\", \"在缺少清晰示例与定义的情况下，理解与识别“aa”的基本特征存在困难。\", \"大班额条件下，学生表达与参与机会受限，影响对“aa”的理解与反馈。\"]}', 1);
