-- ----------------------------
-- Table structure for curriculum_standard
-- ----------------------------
DROP TABLE IF EXISTS `curriculum_standard`;
CREATE TABLE `curriculum_standard`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '标准ID',
  `standard_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准名称',
  `stage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学段',
  `grade_min` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最低年级',
  `grade_max` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '最高年级',
  `core_competency` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '核心素养',
  `content_topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内容主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准内容',
  `performance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '学业表现',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源',
  `source_page` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '页码',
  `embedding_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'FAISS向量ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_curriculum_standard_stage_grade`(`stage` ASC, `grade_min` ASC, `grade_max` ASC) USING BTREE,
  INDEX `idx_curriculum_standard_topic`(`content_topic` ASC) USING BTREE,
  INDEX `idx_curriculum_standard_embedding_key`(`embedding_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2003 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程标准知识表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of curriculum_standard
-- ----------------------------
INSERT INTO `curriculum_standard` VALUES (2001, 'DEMO课程标准条目A（非真实课标）', 'PRIMARY', 4, 6, '信息判断与数字素养', '信息真实性与可靠性判断', 'DEMO：学生在数字化学习活动中能够比较不同来源的信息，并尝试依据证据判断信息是否可靠。', 'DEMO：能够说明判断某条信息可信或不可信的至少一个依据。', 'DEMO_STANDARD_NOT_REAL', 'N/A', 'std_demo_2001', '2026-08-25 15:00:35');
INSERT INTO `curriculum_standard` VALUES (2002, 'DEMO课程标准条目B（非真实课标）', 'PRIMARY', 4, 6, '问题解决与责任意识', '数字工具使用', 'DEMO：学生能够在教师指导下使用数字工具解决问题，并关注工具输出的局限。', 'DEMO：能够在使用数字工具后说明仍需人工检查的内容。', 'DEMO_STANDARD_NOT_REAL', 'N/A', 'std_demo_2002', '2026-08-25 15:00:35');

