DROP TABLE IF EXISTS `decision_log`;
CREATE TABLE `decision_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `decision_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OBJECTIVE/PEDAGOGY/ASSESSMENT',
  `biz_id` bigint UNSIGNED NOT NULL COMMENT '业务ID',
  `ai_proposal_json` json NULL COMMENT 'AI原建议',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ACCEPT/REVISE/REJECT',
  `teacher_revision_json` json NULL COMMENT '教师修改',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_decision_log_project_type`(`project_id` ASC, `decision_type` ASC) USING BTREE,
  INDEX `idx_decision_log_biz`(`decision_type` ASC, `biz_id` ASC) USING BTREE,
  CONSTRAINT `fk_decision_log_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 11074 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教师认知锚点决策日志' ROW_FORMAT = Dynamic;

