INSERT INTO `research_analysis` VALUES (2, 2, 1001, '{\"grade\": \"五、六年级\", \"sampleSize\": 84, \"description\": \"小学高年级学生，DEMO样本84人\", \"educationStage\": \"PRIMARY\"}', '生成式AI回答的信息核验与证据判断', '[\"INFORMATION_VERIFICATION\", \"AI_COGNITION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"先判断后咨询\", \"description\": \"学生在查看AI建议前先形成个人初步判断\"}, {\"name\": \"多来源核验\", \"description\": \"至少使用两个独立信息来源核验AI生成内容\"}, {\"name\": \"同伴证据比较\", \"description\": \"在小组中比较证据并解释观点差异\"}, {\"name\": \"基于证据修订判断\", \"description\": \"根据核验结果接受、修改或拒绝AI建议\"}]', '{\"duration\": \"4周\", \"sessions\": 8, \"description\": \"每周2课时，共8课时的DEMO课堂干预\"}', '[\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"]', '[\"学生在多来源信息核验与证据说明方面表现出较明显改善。\", \"先形成个人判断再接触AI建议，有助于学生识别AI回答与已有证据之间的不一致。\", \"要求学生说明“依据什么证据做出判断”，比只要求回答“可信/不可信”更能呈现其核验过程。\"]', '[\"DEMO样本来自单一学校，外部推广需谨慎。\", \"干预仅持续4周，尚不能说明长期保持与迁移效果。\", \"不同AI工具和信息来源质量可能影响学习表现。\"]', '当前DEMO研究与项目“AI的答案可信吗？”高度匹配。可将核心研究启示概括为：先判断、再咨询AI；要求多来源核验；让学生公开证据并修订判断。教学中需要提供可理解的信息来源、证据记录支架和充分的同伴讨论时间。', '{\"note\": \"Synthetic demo data. Not a real publication.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"limitations\": \"TEACHER_CONFIRMED\", \"intervention\": \"TEACHER_CONFIRMED\", \"mainFindings\": \"TEACHER_CONFIRMED\", \"participants\": \"TEACHER_CONFIRMED\", \"researchTopic\": \"TEACHER_CONFIRMED\", \"assessmentTools\": \"TEACHER_CONFIRMED\", \"teachingStrategies\": \"TEACHER_CONFIRMED\", \"aiLiteracyDimensions\": \"TEACHER_CONFIRMED\"}', 100, 'READY', 1, 2, '2026-09-03 19:26:37', '2026-09-03 19:26:37', '{\"limitations\": [\"单一学校样本\", \"干预周期较短\", \"工具与来源质量可能影响结果\"], \"mainFindings\": [\"多来源核验促进学生关注信息依据\", \"先形成观点后咨询AI有助于识别信息不一致\", \"公开说明证据有助于呈现和修订判断过程\"], \"evidenceReady\": true, \"sourceExcerpt\": \"学生先形成初步判断，再通过至少两个信息来源核验AI回答，并在小组中依据证据修订结论。\", \"researchTopics\": [\"生成式AI信息核验\", \"证据判断\"], \"assessmentTools\": [\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"], \"researchSubjects\": [\"小学五、六年级学生\", \"DEMO样本84人\"], \"teachingStrategies\": [\"先判断后咨询\", \"多来源核验\", \"同伴证据比较\", \"基于证据修订判断\"], \"aiLiteracyDimensions\": [\"信息核验\", \"AI认知\", \"人机有效交互\"], \"interventionDuration\": \"4周，共8课时\", \"teachingImplications\": \"在五年级AI信息核验课程中，可设计“初步判断—AI比较—多来源核验—小组证据讨论—修订结论”的学习链，并要求学生记录证据与最终判断之间的关系。\"}', 'VALIDATED', '2026-09-03 19:30:00', NULL);
INSERT INTO `research_analysis` VALUES (3, 3, 1001, '{\"grade\": \"小学高年级\", \"sampleSize\": 56, \"description\": \"DEMO样本56人\", \"educationStage\": \"PRIMARY\"}', '同伴讨论与生成式AI批判性判断', '[\"INFORMATION_VERIFICATION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"对比AI解释\", \"description\": \"比较不同AI生成解释中的共同点与冲突\"}, {\"name\": \"同伴证据讨论\", \"description\": \"小组成员依据证据解释判断差异\"}]', NULL, '[\"课堂讨论记录\", \"判断理由评分量表\"]', '[\"同伴讨论能够使部分学生更主动地说明自己的证据来源。\", \"当不同AI回答出现冲突时，学生更可能提出进一步核验需求。\"]', '[]', '当前资料已识别研究对象、主题、AI素养、两项教学策略和部分结果；干预时间及研究局限仍未确认，暂不生成正式证据卡。', '{\"note\": \"Incomplete synthetic demo record.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 75, 'INCOMPLETE', 0, 1, '2026-09-03 19:26:37', '2026-09-03 19:26:37', '{\"limitations\": [], \"mainFindings\": [\"同伴讨论促进证据说明\", \"AI回答冲突促进进一步核验\"], \"evidenceReady\": false, \"researchTopics\": [\"同伴讨论\", \"生成式AI批判性判断\"], \"assessmentTools\": [\"课堂讨论记录\", \"判断理由评分量表\"], \"researchSubjects\": [\"小学高年级学生\", \"DEMO样本56人\"], \"teachingStrategies\": [\"对比AI解释\", \"同伴证据讨论\"], \"aiLiteracyDimensions\": [\"信息核验\", \"人机有效交互\"], \"interventionDuration\": null}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (4, NULL, 1013, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:54:55', '2026-09-08 12:54:55', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 7);
INSERT INTO `research_analysis` VALUES (6, NULL, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 3);
INSERT INTO `research_analysis` VALUES (7, NULL, 1001, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 8);
INSERT INTO `research_analysis` VALUES (8, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 18:53:24', '2026-09-08 18:53:24', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\", \"The relationship between GAI use and student demographics\", \"The relationship between GAI use and personality traits (Big Five)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (9, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 2, '2026-09-08 18:54:20', '2026-09-08 18:54:20', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (10, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 3, '2026-09-08 18:54:28', '2026-09-08 18:54:28', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (11, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 4, '2026-09-08 18:54:51', '2026-09-08 18:54:51', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (12, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 5, '2026-09-08 18:55:07', '2026-09-08 18:55:07', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (13, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 6, '2026-09-08 18:55:42', '2026-09-08 18:55:42', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": true, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [\"探究式学习\"], \"intervention_duration\": \"30分钟\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI_COGNITION\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (14, 9, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 19:44:28', '2026-09-08 19:44:28', '{\"limitations\": [\"Experiments primarily focus on non-reasoning LLMs, and evaluation on reasoning-oriented models (e.g., ChatGPT-o1) is needed.\", \"AutoSCORE has not yet been deployed in a real classroom or large-scale student assessment setting.\", \"The work is limited to text-based assessments and does not handle multimodal inputs like images and audio.\", \"Rubric component templates are currently manually derived.\"], \"main_findings\": [\"AutoSCORE predominantly improves scoring accuracy, human-machine agreement (QWK, correlations), and reduces error metrics (MAE, RMSE) compared to single-agent baselines.\", \"The framework shows particularly strong benefits on complex, multi-dimensional rubrics.\", \"The framework yields especially large relative gains on smaller LLMs.\", \"The two-stage design constrains the LLM\'s reasoning path to pass through human-aligned intermediate states, improving interpretability and robustness.\"], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [\"Automated scoring of constructed responses\", \"Large language models in education\", \"Multi-agent framework design\"], \"assessment_tools\": [\"ASAP-SAS\", \"ASAP-AES\", \"Accuracy\", \"Quadratic Weighted Kappa (QWK)\", \"Mean Absolute Error (MAE)\", \"Root Mean Square Error (RMSE)\", \"Pearson correlation\", \"Spearman correlation\"], \"research_subjects\": [\"Grade 10 students\", \"Grade 8 students\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (15, NULL, 1018, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 19:52:45', '2026-09-08 19:52:45', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 12);
INSERT INTO `research_analysis` VALUES (16, 10, 1018, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 19:53:44', '2026-09-08 19:53:44', '{\"limitations\": [\"The controlled lab environment may not fully mirror the complexities of real-world educational settings where multiple visualisations are viewed simultaneously.\", \"The one-hour intervention period limits the ability to assess long-term learning gains.\", \"The participant pool was predominantly from North America and Europe, limiting the generalisability of the findings.\", \"The study did not thoroughly investigate the specific design features of the proactive GenAI agents contributing to their effectiveness.\", \"The evaluation focused on lower levels of Bloom\'s taxonomy (knowledge and comprehension) and did not assess higher-order thinking skills.\"], \"main_findings\": [\"Passive GenAI agents yielded comparable improvements to standalone scaffolding (data storytelling) both during and after the intervention.\", \"Proactive GenAI agents significantly enhanced students\' VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"All three interventions (data storytelling, passive GenAI, proactive GenAI) significantly improved the effectiveness and efficiency of extracting insights from VLA.\", \"The proactive GenAI agent condition showed a significant improvement from the intervention phase to the post-intervention phase, unlike the other conditions.\", \"No significant interaction effects were found between visualisation literacy and intervention conditions, suggesting the interventions were beneficial across literacy levels.\"], \"evidence_ready\": true, \"source_excerpt\": \"The results show that passive agents yield comparable improvements to standalone scaffolding both during and after the intervention. Notably, proactive GenAI agents significantly enhance students’ VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"research_topics\": [\"Generative AI agents\", \"Scaffolding\", \"Visual learning analytics (VLA) comprehension\", \"Data storytelling\"], \"assessment_tools\": [\"mini-Visualisation Literacy Assessment Test (mini-VLAT)\", \"Analytical writing tasks\", \"Multiple-choice evaluation questions (Knowledge and Comprehension levels of Bloom\'s taxonomy)\"], \"research_subjects\": [\"higher education students\"], \"teaching_strategies\": [\"Data storytelling\", \"Passive GenAI agents (reactive support)\", \"Proactive GenAI agents (scaffolding questions and feedback)\"], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"Data visualisation literacy\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (17, 10, 1018, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 2, '2026-09-08 21:01:51', '2026-09-08 21:01:51', '{\"limitations\": [\"The controlled lab environment may not fully mirror the complexities of real-world educational settings where multiple visualisations are viewed simultaneously.\", \"The one-hour intervention period limits the ability to assess long-term learning gains.\", \"The participant pool was predominantly from North America and Europe, limiting the generalisability of the findings.\", \"The study did not thoroughly investigate the specific design features of the proactive GenAI agents contributing to their effectiveness.\", \"The evaluation focused on lower levels of Bloom\'s taxonomy (knowledge and comprehension) and did not assess higher-order thinking skills.\"], \"main_findings\": [\"Passive GenAI agents yielded comparable improvements to standalone scaffolding (data storytelling) both during and after the intervention.\", \"Proactive GenAI agents significantly enhanced students\' VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"All three interventions (data storytelling, passive GenAI, proactive GenAI) significantly improved the effectiveness and efficiency of extracting insights from VLA.\", \"The proactive GenAI agent condition showed a significant improvement from the intervention phase to the post-intervention phase, unlike the other conditions.\", \"No significant interaction effects were found between visualisation literacy and intervention conditions, suggesting the interventions were beneficial across literacy levels.\"], \"evidence_ready\": true, \"source_excerpt\": \"The results show that passive agents yield comparable improvements to standalone scaffolding both during and after the intervention. Notably, proactive GenAI agents significantly enhance students’ VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"research_topics\": [\"Generative AI agents\"], \"assessment_tools\": [\"mini-Visualisation Literacy Assessment Test (mini-VLAT)\", \"Analytical writing tasks\", \"Multiple-choice evaluation questions (Knowledge and Comprehension levels of Bloom\'s taxonomy)\"], \"research_subjects\": [\"higher education students\"], \"teaching_strategies\": [\"Data storytelling\", \"Passive GenAI agents (reactive support)\", \"Proactive GenAI agents (scaffolding questions and feedback)\"], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"Data visualisation literacy\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (18, 10, 1018, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopic\": \"TEACHER\", \"assessmentTools\": \"TEACHER\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 3, '2026-09-08 21:02:21', '2026-09-08 21:02:21', '{\"limitations\": [\"The controlled lab environment may not fully mirror the complexities of real-world educational settings where multiple visualisations are viewed simultaneously.\", \"The one-hour intervention period limits the ability to assess long-term learning gains.\", \"The participant pool was predominantly from North America and Europe, limiting the generalisability of the findings.\", \"The study did not thoroughly investigate the specific design features of the proactive GenAI agents contributing to their effectiveness.\", \"The evaluation focused on lower levels of Bloom\'s taxonomy (knowledge and comprehension) and did not assess higher-order thinking skills.\"], \"main_findings\": [\"Passive GenAI agents yielded comparable improvements to standalone scaffolding (data storytelling) both during and after the intervention.\", \"Proactive GenAI agents significantly enhanced students\' VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"All three interventions (data storytelling, passive GenAI, proactive GenAI) significantly improved the effectiveness and efficiency of extracting insights from VLA.\", \"The proactive GenAI agent condition showed a significant improvement from the intervention phase to the post-intervention phase, unlike the other conditions.\", \"No significant interaction effects were found between visualisation literacy and intervention conditions, suggesting the interventions were beneficial across literacy levels.\"], \"evidence_ready\": true, \"source_excerpt\": \"The results show that passive agents yield comparable improvements to standalone scaffolding both during and after the intervention. Notably, proactive GenAI agents significantly enhance students’ VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\", \"research_topics\": [\"Generative AI agents\"], \"assessment_tools\": [\"mini-Visualisation Literacy Assessment Test (mini-VLAT)\", \"Analytical writing tasks\", \"Multiple-choice evaluation questions (Knowledge and Comprehension levels of Bloom\'s taxonomy)\"], \"research_subjects\": [\"higher education students\"], \"teaching_strategies\": [\"Data storytelling\", \"Passive GenAI agents (reactive support)\", \"Proactive GenAI agents (scaffolding questions and feedback)\"], \"intervention_duration\": \"45min\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"Data visualisation literacy\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (19, NULL, 1002, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 21:03:17', '2026-09-08 21:03:17', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 14);
INSERT INTO `research_analysis` VALUES (20, 11, 1018, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 21:18:00', '2026-09-08 21:18:00', '{\"limitations\": [\"The sample was primarily composed of educational technology majors with uneven gender distribution, limiting generalizability to other disciplines and populations\", \"The instructional tasks focused on research design activities, leaving uncertainty about effectiveness in other learning domains\", \"The six-week intervention duration was relatively short, limiting the ability to examine long-term effects on reflective practices and sustained behavioral change\", \"The number of group-level submissions was small (eight proposals per condition), constraining statistical power and precision of effect estimates\", \"Ethical considerations regarding LLM-based learning processes, including data privacy, content originality, and intellectual property rights, were not comprehensively addressed\"], \"main_findings\": [\"The S-ICA group showed marginal improvement in conceptual knowledge gains compared to the nS-ICA group (Time × Condition interaction ̂𝛽 = 0.821, 𝑝 = 0.056)\", \"The S-ICA group produced significantly higher-quality experimental research proposals (Hedges’ 𝑔 = 1.69, 95% CI [0.57, 2.80]; CLES = 0.88)\", \"S-ICA students reported significantly higher overall reflective thinking, with particularly pronounced differences in Reflection (𝐹 = 11.438, 𝑝 = .001) and Critical Reflection (𝐹 = 13.712, 𝑝 < 0.001)\", \"Epistemic Network Analysis revealed that S-ICA students activated more advanced reflective pathways, showing stronger connections between Understanding–Reflection (U–R, 0.53), Reflection–Critical Reflection (R–CR, 0.43), and Understanding–Critical Reflection (U–CR, 0.32)\", \"No significant difference was found in learning motivation between the groups (𝐹 = 1.749, 𝑝 = 0.190)\", \"Interviews indicated that S-ICA facilitated deep thinking, effective learning, questioning and reflection, knowledge acquisition, and prevention of cognitive dependence, while nS-ICA users reported superficial learning and reliance on ready-made answers\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"Effects of an LLM-based Socratic Intelligent Conversational Agent (S-ICA) on students\' academic performance and reflective thinking in higher education\", \"Integration of Socratic questioning strategies with GenAI/LLM technologies\", \"Comparative study of Socratic vs. non-Socratic conversational agents in inquiry-based learning for research design\"], \"assessment_tools\": [\"Conceptual knowledge pretest and posttest on experimental research methods\", \"Research proposal quality rubric (six dimensions: Research topic, Research question, Theoretical rationale, Research content, Research methodology, Research procedures)\", \"Reflective thinking scale adapted from Kember et al. (1999) measuring four dimensions: Habitual Action, Understanding, Reflection, and Critical Reflection\", \"Learning motivation questionnaire adapted from Chen et al. (2015) measuring Intrinsic Motivation and Extrinsic Motivation\", \"Epistemic Network Analysis (ENA) of dialogue transcripts to model co-occurrence of reflective categories\", \"Semi-structured interviews with selected students to capture learning perceptions and experiences\"], \"research_subjects\": [\"94 second-year undergraduates majoring in Educational Technology from a teacher training university in central China (mean age 19)\"], \"teaching_strategies\": [\"Inquiry-based learning (IBL) framework with Orientation, Conceptualization, Investigation, and Discussion phases\", \"Socratic questioning integrated into LLM-based conversational agents (S-ICA) to promote reflective thinking\", \"Collaborative group work with structured worksheets and turn-taking scaffolds\", \"Scaffolded feedback through adaptive prompt engineering and dynamic dialogue adjustment\", \"Iterative revision cycles guided by AI agents for experimental research proposal development\"], \"intervention_duration\": \"6 weeks\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"Use of large language models (LLM) for learning support\", \"Socratic questioning strategies implemented via AI agents\", \"Inquiry-based learning with AI scaffolding\", \"Reflective thinking supported by conversational agents\", \"Collaborative human–AI learning systems\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (21, NULL, 1019, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 21:20:58', '2026-09-08 21:20:58', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 16);
INSERT INTO `research_analysis` VALUES (22, 12, 1019, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 21:22:16', '2026-09-08 21:22:16', '{\"limitations\": [\"Sample drawn primarily from Educational Technology undergraduates; limited generalizability to other disciplines and populations.\", \"Task focused on research design; it is unclear whether benefits would transfer to other learning domains.\", \"Short six-week intervention; long-term effects on reflective practice and sustained behavior change were not examined.\", \"Small number of group-level proposals (8 per condition) reduced statistical power and precision for team-level outcomes.\", \"Ethical issues of LLM use (privacy, originality, intellectual property) were not comprehensively addressed in the study design.\"], \"main_findings\": [\"S-ICA (Socratic agent) produced substantially higher quality experimental research proposals than nS-ICA (non-Socratic agent), with a large effect size (Hedges’ g = 1.69) and significantly better team-level scores.\", \"S-ICA significantly improved self-reported reflective thinking overall, with the strongest effects in the higher-order dimensions of Reflection and Critical Reflection.\", \"ENA showed S-ICA strengthened mid- to higher-order reflective pathways (e.g., Understanding–Reflection, Reflection–Critical Reflection, Understanding–Critical Reflection), while the control condition showed stronger connections in lower-order pathways (e.g., Habitual Action–Understanding).\", \"Conceptual knowledge gains were substantial in both groups, but the incremental advantage of S-ICA over nS-ICA was small to moderate and at most marginally significant.\", \"No statistically significant difference was found between S-ICA and nS-ICA on learning motivation.\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"Effects of an LLM-based Socratic conversational agent (S-ICA) on students’ academic performance and reflective thinking in higher education\"], \"assessment_tools\": [\"Conceptual knowledge test\", \"Experimental research proposal quality rubric\", \"Reflective thinking scale (Kember et al., 1999; dimensions: Habitual Action, Understanding, Reflection, Critical Reflection)\", \"Learning motivation questionnaire (Chen et al., 2015; subscales: Intrinsic Motivation, Extrinsic Motivation)\", \"Epistemic Network Analysis (ENA) of dialogue transcripts\", \"Semi-structured interviews\"], \"research_subjects\": [\"second-year undergraduates majoring in Educational Technology\"], \"teaching_strategies\": [\"Socratic questioning strategy embedded in an LLM-driven conversational agent (S-ICA)\"], \"intervention_duration\": \"six-week intervention period\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"Academic performance\", \"Reflective thinking\", \"Learning motivation\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (23, NULL, 1011, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 10:17:08', '2026-09-09 10:17:08', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 18);
INSERT INTO `research_analysis` VALUES (24, 13, 1011, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 10:19:26', '2026-09-09 10:19:26', '{\"limitations\": [\"样本量较小且集中于社科背景的研究生群体，可能影响结果的代表性与普适性\", \"实验干预时长有限，系统支持的长期影响仍有待探索\", \"ABCKC-AI虽对低结构观点的支持有效，但对高阶论证结构（如多源证据整合、复杂观点的综合）的促进作用有限\", \"当前学习者—智能体的互动机制相对单一，主要局限于单向提示和对话窗口互动\"], \"main_findings\": [\"ABCKC-AI支持能够显著提高个人论证水平，实验组前后测得分提升显著高于对照组\", \"ABCKC-AI支持的小组协作文档得分显著高于对照组，整体论证质量更佳\", \"实验组在与论证相关的实质性互动上产出更多，包括提出更多主张、更倾向于通过逻辑推理和事实证据增强观点的说服力、更积极主动地回应他人观点；对照组在社会情感互动上更为频繁\", \"实验组的平均论证层级高于对照组，具体层级分布上，实验组1级结构最多（46.13%），对照组0级结构最多（48.60%），实验组在1~3级结构上的比例均高于对照组，说明实验组出现了更多相对复杂的论证结构\", \"实验组的知识建构深度显著高于对照组，实验组更多进入阐释和修正阶段，对照组主要停留在分享和回应观点阶段\", \"学习者对ABCKC-AI支持的论证式协作知识建构整体持满意态度，认同其提示能帮助专注讨论并补充解释和证据，认同其主动插入的观点能启发思路、拓展讨论方向并生成有用的总结，认同其对话支持能帮助完善观点及整合讨论内容\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"多智能体支持论证式协作知识建构\", \"基于大语言模型的多智能体系统（ABCKC-AI）设计与准实验评估\", \"论证式协作知识建构（ABCKC）\"], \"assessment_tools\": [\"GRE写作任务改编的论证水平测试（前测与后测）\", \"协作文档评分（基于已有评分框架，由两位教育技术学专家独立评分）\", \"《ABCKC-AI技术接受度问卷》（涵盖对AI提示论点相关度与论证结构的评价、对AI提供观点刺激的评价、对AI支持对话的评价、对ABCKC-AI的整体评价四个维度）\"], \"research_subjects\": [\"62名大学生（涵盖本科、硕士和博士不同学历层次，学科背景包括自然科学、人文学科、工学、社会科学）\"], \"teaching_strategies\": [\"通过开放性提示进行干预，避免过度脚本化\", \"对学习者在不同维度的实时表现进行个性化评估\", \"在小组的论证水平达到一定程度后，逐渐淡化并撤出干预\", \"提供外部观点刺激，促进讨论的深度和广度\"], \"intervention_duration\": \"70分钟\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"参与维度\", \"论证维度\", \"认知维度\", \"社会共建维度\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (25, 14, 1002, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 11:38:37', '2026-09-09 11:38:37', '{\"limitations\": [\"当前研究资源中尚未找到足够证据支持这一判断\"], \"main_findings\": [\"基于多模态大模型的协作论证支架引发了丰富的协作论证话语转移行为和高阶知识建构观点\", \"总结升华话语转移行为与关键观点密切相关，关键观点是促进知识建构由低阶至高阶跃迁的主导因素\", \"基于多模态大模型的协作论证支架有助于提升知识建构水平，尤其是在意义协商、检验修改与创新应用方面\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"基于多模态大模型的协作论证支架对知识建构的影响\"], \"assessment_tools\": [\"AI素养量表\", \"话语转移行为编码框架\", \"IAM模型（交互分析模型）\"], \"research_subjects\": [\"68名大学二年级学生（男生30人，女生38人）\"], \"teaching_strategies\": [\"多模态开放系统\", \"差异化支持策略\", \"协同共生机理\"], \"intervention_duration\": \"5周\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI技术理解\", \"AI评估\", \"AI应用\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (26, 15, 1002, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 12:24:00', '2026-09-09 12:24:00', '{\"limitations\": [\"本文尚未回应在具体教学智能体或其他人工智能教育产品中内嵌智能化学习支架的具体做法\"], \"main_findings\": [\"本研究提出了学习支架的三种演化形态及典型特征：传统学习支架、技术支持型学习支架以及智能化学习支架\", \"本研究将智能化学习支架划分为动机性、概念性、策略性和元认知四种表征类型\", \"本研究提出了智能技术支持学习支架创变的“辅助—优化—重塑”三层次内涵\", \"本研究从支架表征、支架设计、支架内嵌和支架优化四方面提出智能化学习支架设计的基本原则\", \"本研究构建了包含“需求分析层—AI赋能层—框架设计层—学习环节层”四个层级的智能化学习支架设计流程\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"人机协同教育场景中的智能化学习支架\", \"学习支架的演进历程\", \"智能化学习支架的内涵与表征\", \"智能化学习支架的设计方略\", \"智能化学习支架的发展路向\"], \"assessment_tools\": [], \"research_subjects\": [\"学生\"], \"teaching_strategies\": [\"支架表征流程化、可视化\", \"支架设计个性化、定制化\", \"支架内嵌常态化、循证化\", \"支架优化证据化、智适应化\"], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"动机性\", \"概念性\", \"策略性\", \"元认知\"]}', 'VALIDATED', NULL, NULL);
INSERT INTO `research_analysis` VALUES (27, NULL, 1020, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 13:11:07', '2026-09-09 13:11:07', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 23);
INSERT INTO `research_analysis` VALUES (28, 17, 1020, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-09 14:18:14', '2026-09-09 14:18:14', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL);

-- ----------------------------
-- Table structure for research_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `research_chat_message`;
CREATE TABLE `research_chat_message`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `session_id` bigint UNSIGNED NOT NULL COMMENT '所属会话ID',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息角色：USER/ASSISTANT/SYSTEM',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息正文',
  `message_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '消息类型：TEXT/FILE/PROCESS/ANALYSIS_UPDATE/EVIDENCE_DRAFT',
  `metadata_json` json NULL COMMENT '扩展信息，如附件ID、resourceId、分析更新、来源引用等',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `sequence_no` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_research_chat_message_session`(`session_id` ASC) USING BTREE,
  INDEX `idx_research_chat_message_session_time`(`session_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_research_chat_message_role`(`session_id` ASC, `role` ASC) USING BTREE,
  INDEX `idx_research_chat_message_type`(`session_id` ASC, `message_type` ASC) USING BTREE,
  CONSTRAINT `fk_research_chat_message_session` FOREIGN KEY (`session_id`) REFERENCES `research_chat_session` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联多轮研究对话消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_chat_message
-- ----------------------------
INSERT INTO `research_chat_message` VALUES (7, 2, 'SYSTEM', '已载入研究资源《DEMO研究：小学高年级学生AI信息核验能力培养——多来源比较与证据判断》，研究文本已完成解析。', 'PROCESS', '{\"stage\": \"ANALYZED\", \"resourceId\": 2}', '2026-09-03 19:20:05', 1);
INSERT INTO `research_chat_message` VALUES (8, 2, 'USER', '我正在为五年级设计“AI的答案可信吗？”这节课。这项研究和我的教学主题匹配吗？请重点看研究对象、研究问题和对信息核验能力的支持。', 'TEXT', NULL, '2026-09-03 19:21:00', 2);
INSERT INTO `research_chat_message` VALUES (9, 2, 'ASSISTANT', '匹配度较高。研究对象是小学五、六年级学生，与当前五年级项目处于同一学段；研究主题直接聚焦生成式AI回答的信息核验与证据判断。对你的课程最有价值的是，它没有把“识别AI错误”停留在概念介绍，而是让学生实际经历“形成判断—寻找证据—比较来源—修订结论”的过程。\n\n**研究对象**：小学高年级学生，DEMO样本84人。\n\n**核心研究问题**：学生如何依据外部证据判断AI回答是否可信，并在出现不一致时修订原有判断。\n\n**与你课程的关联**：可直接支持“信息核验”和“人机判断责任”两个教学重点。', 'TEXT', '{\"analysisPatch\": true, \"readinessScore\": 72, \"suggestedQuestions\": [\"这项研究具体采用了哪些教学策略？\", \"哪些策略适合五年级课堂？\", \"实施这些策略需要什么条件？\"]}', '2026-09-03 19:21:18', 3);
INSERT INTO `research_chat_message` VALUES (10, 2, 'USER', '我更关心教学策略。请把研究中的策略整理成我容易用于课程设计的方式，但先不要直接帮我生成完整教学方案。', 'TEXT', NULL, '2026-09-03 19:23:00', 4);
INSERT INTO `research_chat_message` VALUES (11, 2, 'ASSISTANT', '可以先提炼为4条可迁移的教学原则，而不直接生成活动方案：\n\n**1. 先判断，再咨询AI**：先让学生形成自己的初步判断，避免AI回答成为唯一思考起点。\n\n**2. 强制多来源核验**：要求至少使用两个独立来源验证AI生成内容。\n\n**3. 让证据公开化**：学生不仅给出“可信/不可信”的结论，还要说明使用了什么来源和证据。\n\n**4. 要求修订而非只判断**：比较核验前后的判断，让学生明确哪些AI建议被接受、修改或拒绝，以及为什么。\n\n这些原则可以作为后续“课程智设”的研究依据，但当前仍停留在研究证据解释层。', 'TEXT', '{\"sourceLabel\": \"DEMO研究文本·教学策略部分\", \"analysisPatch\": true, \"readinessScore\": 86}', '2026-09-03 19:23:22', 5);
INSERT INTO `research_chat_message` VALUES (12, 2, 'USER', '这些策略实施时有哪些必要条件？我班里是五年级学生，每人可以使用电脑，但我担心他们只会照抄AI回答。', 'TEXT', NULL, '2026-09-03 19:25:00', 6);
INSERT INTO `research_chat_message` VALUES (13, 2, 'ASSISTANT', '研究提示至少有三个实施条件。\n\n**第一，信息来源必须可访问且可理解。** 五年级学生即使有电脑，如果核验来源过于专业，也很难真正完成证据比较。\n\n**第二，需要显性的证据记录支架。** 可以要求学生记录“AI的主张—核验来源—关键证据—我的判断”，减少直接复制AI回答。\n\n**第三，需要保留同伴讨论时间。** 研究中的修订往往发生在学生看到不同证据或不同观点以后。\n\n针对你担心的“照抄AI”，最直接的设计原则是：在第一次查看AI回答前先提交个人判断，并要求最终结论说明与初始判断相比发生了什么变化。', 'TEXT', '{\"analysisPatch\": true, \"readinessScore\": 94, \"implementationConditions\": [\"可访问且适龄的信息来源\", \"证据记录支架\", \"充分的同伴讨论时间\"]}', '2026-09-03 19:25:28', 7);
INSERT INTO `research_chat_message` VALUES (14, 2, 'USER', '最后帮我把研究结果和局限一起考虑一下。我不希望证据卡把这个研究说得过头。', 'TEXT', NULL, '2026-09-03 19:27:00', 8);
INSERT INTO `research_chat_message` VALUES (15, 2, 'ASSISTANT', '可以。更稳妥的表述应把“发现”和“适用边界”放在一起。\n\n**主要发现**：在这组DEMO课堂数据中，多来源核验、公开说明证据以及基于证据修订判断，与学生更主动地检查AI回答依据相伴出现。\n\n**不应过度推断的地方**：该DEMO研究只来自单一学校，干预4周，因此不能据此声称策略对所有学生都长期有效；不同AI工具、信息来源质量和教师支架方式也可能改变效果。\n\n因此证据卡建议使用“在类似小学高年级课堂中显示出支持作用”这类边界清楚的语言，而不是写成“已经证明一定有效”。', 'TEXT', '{\"analysisPatch\": true, \"readinessScore\": 100, \"readinessStatus\": \"READY\"}', '2026-09-03 19:27:30', 9);
INSERT INTO `research_chat_message` VALUES (16, 2, 'SYSTEM', '8项核心研究信息已完成结构化整理，当前证据准备状态为 READY。', 'ANALYSIS_UPDATE', '{\"analysisId\": 2, \"readinessScore\": 100, \"readinessStatus\": \"READY\"}', '2026-09-03 19:28:00', 10);
INSERT INTO `research_chat_message` VALUES (17, 2, 'SYSTEM', '当前核心研究信息已完整，系统已生成研究证据卡草稿。', 'EVIDENCE_DRAFT', '{\"cardStatus\": \"DRAFT\", \"evidenceCardId\": 5005}', '2026-09-03 19:29:00', 11);
INSERT INTO `research_chat_message` VALUES (18, 2, 'SYSTEM', '教师已检查研究发现、适用对象、推荐策略、实施条件、教学转化建议和研究局限，并确认保存为正式研究证据。', 'EVIDENCE_DRAFT', '{\"cardStatus\": \"CONFIRMED\", \"evidenceCardId\": 5005, \"readinessScore\": 100}', '2026-09-03 19:32:00', 12);
INSERT INTO `research_chat_message` VALUES (19, 3, 'USER', '你是谁', 'TEXT', NULL, '2026-09-07 23:30:33', 1);
INSERT INTO `research_chat_message` VALUES (20, 3, 'ASSISTANT', '我是研教智联助手（Research-to-Design Evidence Agent），面向教师，专注于帮助把研究资源中的可靠证据转化为可理解、可判断、可追溯、可用于课程设计的教学依据。我会支持您完成研究理解、证据提取与判断、教学转化等环节，但最终的教学决策权始终由您掌握。', 'TEXT', NULL, '2026-09-07 23:30:40', 2);
INSERT INTO `research_chat_message` VALUES (21, 3, 'USER', '帮我简单构思一个智慧农业项目', 'TEXT', NULL, '2026-09-07 23:31:08', 3);
INSERT INTO `research_chat_message` VALUES (22, 3, 'ASSISTANT', '针对二年级1课时的“aa”主题，智慧农业项目可围绕“植物生长的数字化观察”展开：以简易物联网传感器为核心载体，让学生通过手机或平板实时查看土壤湿度、光照数据，用可视化图表记录植物生长变化，在“发现问题（植物缺水）—设计方案（调整浇水）—验证效果”的探究流程中，理解智慧农业如何用技术解决实际种植问题，同时落实观察、记录与简单的数据关联能力培养，契合低学段直观体验、动手操作的学习特点。', 'TEXT', NULL, '2026-09-07 23:31:17', 4);
INSERT INTO `research_chat_message` VALUES (23, 3, 'USER', 'hello', 'TEXT', NULL, '2026-09-08 00:04:46', 5);
INSERT INTO `research_chat_message` VALUES (24, 3, 'ASSISTANT', '针对二年级1课时的“aa”主题，智慧农业项目可围绕“植物生长的数字化观察”开展：以简易物联网传感器为工具，让学生借助手机或平板实时监测土壤湿度、光照数据，用可视化图表记录植物变化，在“发现问题（如植物缺水）—设计方案（调整浇水）—验证效果”的探究过程中，感知智慧农业如何借助技术解决种植问题，契合低学段直观体验、动手操作的学习特点，同时培养观察记录与简单的数据关联意识。', 'TEXT', NULL, '2026-09-08 00:04:53', 6);
