INSERT INTO `research_chat_message` VALUES (59, 3, 'ASSISTANT', '你好！我是研教智联助手（Research-to-Design Evidence Agent），专注于帮助教师理解研究证据，并将其可靠地转化为教学依据。\n\n如果你有具体的研究资源需要分析，或者正在构思某个教学项目，随时告诉我你的需求，我们可以一起按照“研究理解→证据判断→证据卡→教学转化”的链路推进，确保每一步都有据可依。\n\n目前你还没有上传具体的研究材料或说明教学背景，如果你准备好了，请直接把相关资料或问题发给我，我会立刻协助你开展工作。', 'TEXT', '{\"projectId\": 1012, \"conversationId\": 3, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-08 18:52:39', 18);
