INSERT INTO `research_chat_message` VALUES (91, 14, 'ASSISTANT', '根据当前项目提供的研究分析与证据材料，尚未检索到与“AI基础认知”主题相关的具体研究信息，因此无法明确回答已有研究主要关注哪些教学或学习问题。\n\n若后续您补充上传了相关的研究论文或资料，我可以帮您进一步梳理其中围绕AI基础认知所探讨的教学与学习核心议题。', 'TEXT', '{\"projectId\": 1002, \"conversationId\": 14, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 11:39:00', 2);
INSERT INTO `research_chat_message` VALUES (92, 22, 'SYSTEM', '当前核心研究信息已经完整，系统已生成证据卡草稿。', 'TEXT', 'null', '2026-09-09 12:24:00', 1);
INSERT INTO `research_chat_message` VALUES (93, 23, 'USER', '围绕当前课程主题，这个论文的研究主要关注哪些教学或学习问题？', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:18:41', 1);
INSERT INTO `research_chat_message` VALUES (94, 23, 'ASSISTANT', '这篇论文主要关注的核心教学与学习问题，围绕“人机协同教育场景中，如何设计与应用智能化学习支架以促进学习”展开，具体包括以下几方面：\n\n1. **人机协同教育场景下，学习支架的内涵与设计缺失问题**\n论文指出，现有研究尚未对智能化学习支架的内涵性表征、设计流程与实践路径做出明确规约，其学理性建构工作也未开展，因此需要从理论层面探讨人机协同场景中智能化学习支架的内涵与设计方略，以填补这一空白。\n\n2. **如何利用智能技术弥合学生最近发展区的核心教学议题**\n在人机协同教育中，如何利用智能技术为学生提供有效支持，帮助其顺利穿越“最近发展区”以完成学习目标，是决定人机协同教学成效的关键问题，而智能化学习支架正是解决这一问题的核心抓手。\n\n3. **学习支架的演进与有效供给问题**\n论文梳理了学习支架从形式增强到智适应增强的演进历程，关注学习支架应具备的高阶性、灵活伴随性、渐隐性和迁移性特征，以及如何通过智能技术实现支架的即时供给与适时撤销，以适配学生的知识建构过程。\n\n4. **智能化学习支架与教学智能体的集成协同问题**\n智能化学习支架无法脱离智能教学工具独立存在，论文聚焦如何推进学习支架嵌入以教育大模型为底层逻辑的教学智能体，实现“教育任务设定”“教育能力实现与拓展”等功能，并通过多模态学习行为分析，实现数据驱动的支架伴随性供给与修订，解决支架与智能工具的集成协同难题。\n\n5. **人机协同分工下学习支架的优化创生问题**\n论文强调在支架生成过程中，教师与智能技术如何协同分工，既发挥智能技术的决策性智能和自适应供给能力，又保留教师在复杂场景下的决策性智慧，以实现学习支架的最优化创生与应用，这是人机协同支架设计的核心实践问题。\n\n6. **学理与实践的鸿沟弥合问题**\n针对学习支架的学理建构与教学实践脱节的问题，论文提出自上而下（以学习理论驱动，用实践数据验证优化）和自下而上（以实践数据为支点，返溯学理优化支架）两条执行进路，核心是发挥数据在学理与实践之间的调节作用，推动学习科学理论的场域性革新与适配。\n\n需要说明的是，当前研究资源中未明确提及该研究的样本学段、具体干预时长及直接针对AI伦理主题的教学策略，其核心关注点聚焦于人机协同场景下学习支架的理论建构与技术实现逻辑，对当前四年级AI伦理课程而言，可作为理解AI技术如何辅助教学的参考，但需结合课程主题和学段特点进一步转化。', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:19:04', 2);
INSERT INTO `research_chat_message` VALUES (95, 23, 'USER', '针对当前项目中的学生群体，已有研究有哪些相关发现？', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:19:34', 3);
INSERT INTO `research_chat_message` VALUES (96, 23, 'ASSISTANT', '要回答“针对当前项目中的学生群体，已有研究有哪些相关发现”，需要先明确两个关键前提：**当前项目的学生群体特征**（如学段、年龄、学科基础、学习需求等），以及**已上传的研究资源内容**。目前我尚未掌握这两部分信息，因此无法直接定位与当前学生群体匹配的研究结论。\n\n若您能补充以下信息，我可以帮您精准梳理相关发现：\n1. **当前项目的学生群体细节**：比如是小学/中学/高中哪个学段？具体年龄范围？学科背景（如语文、数学、科学等）？是否有特殊学习需求（如注意力差异、学习基础薄弱等）？\n2. **您已上传的研究资源**：若已上传论文、报告等研究材料，请告知或直接提供，我会从这些资源中提取与当前学生群体直接相关的研究发现，并严格区分“研究明确报告的事实”“基于结果的解释”“对当前教学的启示”，确保证据可追溯。\n\n请您补充上述信息后，我会立刻为您开展针对性的研究梳理与证据分析。', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:19:44', 4);
INSERT INTO `research_chat_message` VALUES (97, 23, 'USER', '哪些教学策略得到这个研究的支持，并适合当前课程？', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:20:45', 5);
INSERT INTO `research_chat_message` VALUES (98, 23, 'ASSISTANT', '要回答“哪些教学策略得到这个研究的支持，并适合当前课程”，我需要先明确两点：\n\n1. **当前研究资源的具体信息**：您尚未上传或提供具体的研究论文、摘要或已提取的文本，我无法直接从原文中定位“被研究支持的教学策略”。\n2. **当前课程的关键背景**：例如学段（小学/中学/大学）、学科、学生基础、教学目标、可用课时、教学条件（如是否有AI工具支持）等，这决定了研究结论的迁移边界与适用性。\n\n请您补充以下信息，我将严格基于研究原文，为您完成“证据提取→证据判断→教学转化”的链路：\n\n### 需要您提供的信息\n1. **研究资源**：上传论文原文、摘要，或粘贴已提取的关键文本（例如干预措施、策略、方法、结论等）；\n2. **当前课程背景**：学段、学科、核心教学目标、学生特点（如基础水平、认知特点）、课堂时长/频率、可用资源（如是否有AI工具、实验设备等）。\n\n### 后续我将为您完成的工作\n1. **提取研究明确支持的教学策略**：仅从原文中提取研究实际验证/报告的策略，标注原文证据（sourceExcerpt），绝不虚构；\n2. **判断迁移边界**：明确研究样本、情境与当前课程的差异，说明哪些策略可直接参考，哪些需调整（例如“研究基于初中生，当前为小学高年级，需简化策略复杂度”）；\n3. **锚定课程适配性**：结合您的课程目标、学生特点，分析策略的适用条件，区分“研究事实”“合理解释”“课程启示”，不把推测伪装成研究结论。\n\n请您补充上述信息后，我会第一时间为您梳理可落地的策略依据。', 'TEXT', '{\"projectId\": 1020, \"conversationId\": 23, \"deliveryStatus\": \"COMPLETED\"}', '2026-09-09 14:21:02', 6);

-- ----------------------------
-- Table structure for research_chat_session
-- ----------------------------
DROP TABLE IF EXISTS `research_chat_session`;
CREATE TABLE `research_chat_session`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '对话会话ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '当前教师用户ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '所属课程设计项目ID',
  `resource_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '当前会话主要关联的研究资源ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会话标题',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '会话状态：ACTIVE/COMPLETED/ARCHIVED',
  `evidence_card_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '本次会话最终生成的Evidence Card ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `conversation_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `conversation_summary_through_sequence_no` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_research_chat_session_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_research_chat_session_evidence`(`evidence_card_id` ASC) USING BTREE,
  CONSTRAINT `fk_research_chat_session_evidence` FOREIGN KEY (`evidence_card_id`) REFERENCES `evidence_card` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_resource` FOREIGN KEY (`resource_id`) REFERENCES `research_resource` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联多轮研究对话会话表' ROW_FORMAT = Dynamic;

