  INDEX `idx_research_resource_type`(`resource_type` ASC) USING BTREE,
  INDEX `idx_research_resource_doi`(`doi` ASC) USING BTREE,
  INDEX `idx_research_resource_project_sha256`(`project_id` ASC, `sha256` ASC) USING BTREE,
  INDEX `idx_research_resource_project_index_status`(`project_id` ASC, `index_status` ASC) USING BTREE,
  CONSTRAINT `fk_research_resource_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_resource_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_research_resource_index_status` CHECK (`index_status` in (_utf8mb4'pending',_utf8mb4'parsing',_utf8mb4'indexing',_utf8mb4'ready',_utf8mb4'error'))
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联原始研究资源表' ROW_FORMAT = Dynamic;

