INSERT INTO `research_resource` VALUES (2, 1, 1001, 'UPLOAD', 'DEMO研究：小学高年级学生AI信息核验能力培养——多来源比较与证据判断', 'DEMO研究团队', 2026, 'DEMO_小学AI信息核验研究.pdf', 'demo://research/demo_ai_information_verification.pdf', 'application/pdf', 428560, NULL, '10.0000/demo.research.ai-verification.2026.001', 'REVIEWED', '【DEMO研究文本，非真实论文】本研究以小学五、六年级84名学生为对象，围绕“如何判断生成式AI回答是否可信”开展4周、8课时的课堂干预。教学活动包括：学生先形成个人判断，比较两个不同AI回答，使用至少两个外部信息来源进行核验，在小组内说明证据并修订最终判断。研究通过信息核验表现任务、证据记录单、课堂观察和学生反思进行评价。Demo结果显示，学生在多来源核验、证据说明和对AI回答进行修订方面表现出较明显改善；其中，能够在接触AI建议前先形成初步观点的学生，更容易识别AI回答与已有证据之间的不一致。研究同时指出，教学效果依赖于教师提供可理解的核验来源、明确的证据记录支架以及足够的小组讨论时间。局限包括样本来自单一学校、干预周期较短，且未考察长期迁移。本段仅用于系统演示，不可作为真实研究引用。', NULL, '2026-09-03 19:26:37', '2026-09-08 15:26:12', 'DEMO_小学AI信息核验研究.pdf', 'demo://research/demo_ai_information_verification.pdf', 'application/pdf', 428560, 'a10fc5c7bf34ae20a10fc5c7bf34ae20a10fc5c7bf34ae20a10fc5c7bf34ae20', 'a10fc5c7bf34ae20a10fc5c7bf34ae20a10fc5c7bf34ae20a10fc5c7bf34ae20', NULL, 'pending', NULL);
INSERT INTO `research_resource` VALUES (3, 1, 1001, 'UPLOAD', 'DEMO研究：同伴讨论支持的小学生生成式AI批判性判断', 'DEMO研究团队', 2026, 'DEMO_AI批判性判断与同伴讨论.docx', 'demo://research/demo_peer_discussion_ai_judgment.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 186420, NULL, '10.0000/demo.research.ai-verification.2026.002', 'ANALYZED', '【DEMO研究文本，非真实论文】该研究关注小学高年级学生在比较AI生成解释时如何通过同伴讨论发现证据冲突。当前系统已识别研究对象、研究主题、教学策略、评价工具和部分主要发现，但研究局限和具体干预周期仍待进一步确认。本段仅用于展示“研究解析尚未完成”的界面状态。', NULL, '2026-09-03 19:26:37', '2026-09-08 15:26:12', 'DEMO_AI批判性判断与同伴讨论.docx', 'demo://research/demo_peer_discussion_ai_judgment.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 186420, 'b20fc5c7bf34ae20b20fc5c7bf34ae20b20fc5c7bf34ae20b20fc5c7bf34ae20', 'b20fc5c7bf34ae20b20fc5c7bf34ae20b20fc5c7bf34ae20b20fc5c7bf34ae20', NULL, 'pending', NULL);
INSERT INTO `research_resource` VALUES (4, 1, 1012, 'UPLOAD', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'FAILED', NULL, 'PDF text extraction dependency is not installed', '2026-09-06 18:32:15', '2026-09-08 15:26:12', 'Multimodality_of_AI_for_Education_Toward_Artificial_General_Intelligence.pdf', '1/1012/d48587f5a29247a59ad1c3da6109dd73_Multimodality_of_AI_for_Education_Toward_Artificial_General_Intelligence.pdf', 'application/pdf', 2078929, '23cb54a8334155287b3476d8bd1763f1fff1c5838ca21c885ecd69111891cb67', '23cb54a8334155287b3476d8bd1763f1fff1c5838ca21c885ecd69111891cb67', NULL, 'pending', NULL);
INSERT INTO `research_resource` VALUES (5, 1, 1012, 'UPLOAD', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'FAILED', NULL, 'PDF text extraction dependency is not installed', '2026-09-06 19:25:28', '2026-09-08 15:26:12', 'Multimodality_of_AI_for_Education_Toward_Artificial_General_Intelligence.pdf', '1/1012/065a59c4bdc3436ca34eccef72924035_Multimodality_of_AI_for_Education_Toward_Artificial_General_Intelligence.pdf', 'application/pdf', 2078929, '23cb54a8334155287b3476d8bd1763f1fff1c5838ca21c885ecd69111891cb67', '23cb54a8334155287b3476d8bd1763f1fff1c5838ca21c885ecd69111891cb67', NULL, 'pending', NULL);
INSERT INTO `research_resource` VALUES (6, 1, 1012, 'UPLOAD', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'TEXT_EXTRACTED', '666 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nMultimodality of AI for Education: Toward\nArtiﬁcial General Intelligence\nGyeonggeon Lee, Lehong Shi, Ehsan Latif , Yizhu Gao, Arne Bewersdorff, Matthew Nyaaba , Shuchen Guo,\nZhengliang Liu , Gengchen Mai , Tianming Liu , and Xiaoming Zhai\nAbstract—This article addresses the growing importance of un-\nderstanding how multimodal artiﬁcial general intelligence (AGI)\ncan be integrated into educational practices. We ﬁrst reviewed\nthe theoretical foundations of multimodality in human learning,\nencompassing its concept and history, dual coding theory and mul-\ntimedia theory, V ARK multimodality, and multimodal assessment\n(see Section II-A). After that, we revisited the essential components\nof AGI, particularly focusing on the multimodal nature of AGI\nthat distinguished it from artiﬁcial narrow intelligence. Based on\nits conversational functionality, multimodal AGI is considered an\neducational agent already tested in various educational situations\n(see Section II-B). How signiﬁcant text, image, audio, and video\nmodalities are for education, the technological backgrounds of AGI\nfor analyzing and generating them, and educational applications\nof artiﬁcial intelligence (AI) for each modality were thoroughly\nreviewed (Sections III–VI). Finally, we comprehensively investi-\ngated the ethics of AGI in education, originating from the ethics\nof AI and speciﬁed in three strands: ﬁrst, data privacy and ethical\nintegrity, second, explainability, transparency, and fairness, and\nthird, responsibility and decision-making. Practical implementa-\ntion of ethical AGI frameworks in education was reviewed (see\nSection VII). This article also discusses the implications for learning\ntheories, derived operational design principles, current research\ngaps, practical constraints and institutional readiness, and future\ndirections (see Section VIII). This exploration aims to provide an\nReceived 25 May 2024; revised 6 October 2024, 28 January 2025, and 8 May\n2025; accepted 24 May 2025. Date of publication 28 May 2025; date of current\nversion 3 July 2025. This work was supported by the Institute of Education\nSciences, U.S. Department of Education, under Grant R305C240010 (PI Zhai).\n(Corresponding author: Xiaoming Zhai.)\nGyeonggeon Lee is with the AI4STEM Education Center and the Department\nof Mathematics, Science, and Social Studies Education, University of Georgia,\nAthens, GA 30602 USA, and also with the Natural Sciences and Science\nEducation Department, National Institute of Education, Nanyang Technological\nUniversity, Singapore 637616.\nLehong Shi is with the Department of Workforce Education and Instructional\nTechnology, University of Georgia, Athens, GA 30602 USA.\nEhsan Latif, Yizhu Gao, and Xiaoming Zhai are with the AI4STEM Educa-\ntion Center and the Department of Mathematics, Science, and Social Studies\nEducation, University of Georgia, Athens, GA 30602 USA (e-mail: xiaom-\ning.zhai@uga.edu).\nArne Bewersdorff is with the Technical University of Munich, 80333 Munich,\nGermany.\nMatthew Nyaaba is with the AI4STEM Education Center and the Department\nof Educational Theory and Practice, University of Georgia, Athens, GA 30602\nUSA.\nShuchen Guo is with the AI4STEM Education Center and the Department\nof Mathematics, Science, and Social Studies Education, University of Georgia,\nAthens, GA 30602 USA, and also with the School of Teacher Education, Nanjing\nNormal University, Nanjing 210097, China.\nZhengliang Liu and Tianming Liu are with the School of Computing and the\nDepartment of Geography, University of Georgia, Athens, GA 30602 USA.\nGengchen Mai is with the Department of Geography and the Environment,\nUniversity of Texas at Austin, Austin, TX 30602 USA.\nDigital Object Identiﬁer 10.1109/TLT.2025.3574466\nadvanced understanding of the intersection between AI, multi-\nmodality, and education, setting a foundation for future research\nand development.\nIndex Terms —Artiﬁcial general intelligence (AGI), artiﬁcial\nintelligence (AI), ChatGPT, education, generative pretrained\nTransformer (GPT)-4, Gemini, machine learning, multimodality.\nI. I NTRODUCTION\nI\nNTEGRATING artiﬁcial intelligence (AI) in the classroom\nhas become a transformative force as the educational land-\nscape continually evolves. Inspired by the recent development\nof GPT-4V [1] and Gemini [2], the idea of multimodality in\nAI for education heralds a synergy of various sensory channels\nand cognitive strategies to enhance teaching, learning, and as-\nsessment. This exploration commences with an exposition of the\nmultimodal nature of learning [3] and the consequent imperative\nfor educational technologies to cater to this diversity. With its\ncapacity to process and synthesize vast streams of multimodal\ninformation, AI is a potent ally in this regard [4]. Particularly,\nit is evidenced that the multimodal AI applications cast light on\nthe way toward artiﬁcial general intelligence (AGI) within the\neducational domain.\nAGI is a hypothetical machine able to understand, learn,\nand apply knowledge across a range of cognitive tasks at a\nhuman-like level [5]. Recent progress in AI technologies spans a\nwide spectrum of intelligence in text, graphic, video, and audio\nanalysis and generation. OpenAI claimed pioneering research\non the path to AGI—“We believe our research will eventually\nlead to artiﬁcial general intelligence, a system that can solve\nhuman-level problems. Building safe and beneﬁcial AGI is our\nmission” [6]. Google also deployed Gemini, which reportedly\noutperforms human experts since it “is built from the ground up\nfor multimodality - reasoning seamlessly across text, images,\nvideo, audio, and code” [7]. While AGI remains a nascent\naspiration, conceptualizing the integration of multimodal AGI\ninto education paves the way for incoming groundbreaking\ninnovations that are redeﬁning traditional teaching and learning\nparadigms.\nThrough this article, we provide a conceptual framework for\nunderstanding the role of multimodal AGI in educational set-\ntings. Fig.1 shows the overview of the framework. We conducted\na logical literature review to organize emerging topics of AGI\nfor education. The rest of this article is organized as follows.\n1) We juxtapose the theoretical foundations of multimodality\nin human learning and AGI in Section II.\n1939-1382 © 2025 IEEE. All rights reserved, including rights for text and data mining, and training of artiﬁcial intelligence and similar technologi es.\nPersonal use is permitted, but republication/redistribution requires IEEE permission. See https://www.ieee.org/publications/rights/index. html for more information.\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 667\nFig. 1. Framework of multimodal AGI for education.\n– The concept, history, theories, and application of mul-\ntimodality in human learning are given in Section II-A.\n– How and why multimodality is an essential character-\nistic of AGI is given in Section II-B.\n2) Then, we dive into speciﬁc data modalities, such as text,\ngraphics, audio, and video that AGI can analyze and\ngenerate for education in Sections III–VI.\n3) In Section VII, we formulate that the destination of mul-\ntimodal AGI for education should be its ethical use.\n4) We discuss implications for learning theories, derived\ndesign principles, current research gaps, practical con-\nstraints, and future directions in Section VIII. Finally,\nSection IX concludes this article.\nII. T HEORETICAL FOUNDA TIONS OFMULTIMODALITY IN\nHUMAN LEARNING AND AGI\nA. Multimodality in Human Learning\n1) Concept and History of Multimodality in Education: The\nlearning and information processing channels in the human\nmind are notably impactful across diverse educational activities.\nOne of the most noteworthy manifestations is the fusion and\nsynergy of multimodality in education [8]. The different types\nof information media, including text, image, sound, gaze, etc.,\nare referred to as “modalities,” with each of them partially\ncontributing to sense-making and playing a discrete role in the\nwhole process of learning [8].\nResearchers have realized the multimodal nature of human\nlearning for centuries, which traces back to John Amos Come-\nnius’s milestone work Orbis Pictus (1st ed., 1658) [9], [10].\nOrbis Pictus presented its content in children’s mother tongue,\nLatin language, and images of the objects being explained in\nthe two languages simultaneously, serving as an early model for\nintegrating the visual and lexical approaches.\nFig. 2. Dual coding theory.\nIn the 19th century, magic lantern slides emerged as learn-\ning media to convey information, which served as the early\nversion of the projector as a milestone for visual aid. In the\nearly 20th century (1900–1950), motion pictures in the forms\nof ﬁlm, television, or simulations signiﬁcantly increased the\namount of information conveyed in classroom learning [10].A s\naudio–visual media were increasingly being adopted in schools,\nmuseums, and libraries, particularly after World War II, there\nwas a practical need to uncover how multimedia plays a role in\nlearning processes [11].\n2) Dual-Coding Theory and Multimedia Theory: To reveal\nhow multimedia assists in learning, it is critical to understand\nthe human information processing system. Paivio [12] believed\nthat humans possess two cognitive subsystems: a verbal system\nto process linguistic information, such as language and text,\nand an imagery system to process nonverbal information, such\nas image sensory. While the former is good at sequential and\nsymbolic information processing, the latter is better at holistic\nand spatial information processing. The two distinct systems\ncollaboratively interact to enhance memory and sense-making\n(Fig. 2).\nIn addition, Paivio [12] hypothesized that when students\nlearn from multimedia with verbal and visual explanations of\na given phenomenon, they ﬁrst build mental representations ofAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n668 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nFig. 3. V ARK multimodality.\nverbal and visual systems, respectively, and construct referential\nconnections between the two. Paivio’s theory is characterized as\na dual coding theory based on its features.\nAligned with the dual coding theory, Mayer and Sims [3]\nfurther pointed out that building mental representations of ex-\nternal sensory stimuli and constructing referential connections\nbetween the visual and verbal representations occur in students’\nworking memory. Given the constraints of working memory,\neach channel (i.e., auditory and visual) has a limited capacity\nfor processing information. Overloading any of the channels can\nimpede learning and information retention. Therefore, education\nshould consider the intensity of information provided to learners\nand the channel used to aid student learning. For example, when\nstudents read a text-based problem to ﬁgure out why the Sun\nrises in the east and sets in the west, they must ﬁrst transform the\ntext into visual information, retrieving everyday experience from\nlong-term memory. Meanwhile, they must retrieve scientiﬁc\nknowledge about circular motion and Newton’s laws in text\nand image [13], which can be highly cognitively intensive.\nTherefore, appropriate strategies to assist problem-solving are\nessential to facilitate learning.\nStudies have examined the effect of multimedia learning.\nIn a meta-analysis, the overall weighted mean effect size of\nmultimedia learning compared to the single-media control group\nwas moderate to large, d = 0.72 (95% conﬁdence interval 0.52–\n0.92) [14]. One of the largest effect sizes was reported by Moreno\nand Mayer [15], tested in a computer-mediated botany class\n(upto d = 2.11–2.52). The success of dual-coding or multimedia\ntheory in learning can also be attributed to reduced cognitive\nload, which could be higher when information is delivered only\nthrough the verbal channel [16].\n3) Visual, Aural, Read/Write, and Kinesthetic (VARK) Multi-\nmodality Framework: Researchers found that learning extends\nbeyond media types and to communication modes. Fleming and\nMills [17] proposed the visual, aural, read/write, and kinesthetic\n(V ARK) framework for multimodal learning (see Fig. 3). They\ngrounded their assertions on cognitive science, such as neuro-\nlinguistic programming, split-brain research, and left/right brain\nmodalities [17]. Fleming and Mills [17] 1) were deeply con-\ncerned with students’ metacognition on their learning styles, 2)\ndifferentiated “visual” preferences for graphical and symbolic\nrepresentation from “Read/Write” for printed representation,\nand 3) provided learning strategies that correspond to indi-\nvidual learners’ preferred combinations of learning modalities.\nHowever, they primarily focused on the practical use of the\ninventory and did not provide construct validity or reliability\nof the instrument [17].\nFollow-up studies have revised and validated the V ARK\nquestionnaire [18], investigated the distribution of preferred\nlearning modalities among students, and showed the effective-\nness of V ARK multimodal teaching and learning [19].T h e\nV ARK multimodality is frequently referenced in educational\ntechnology and artiﬁcial intelligence in education (AIEd) ﬁelds\nas well. Chen and Wang [20] showed that the V ARK-inspired\naugmented-reality-embedded individualized instruction effec-\ntively increased student achievement. Lee et al. [21] developed\nan AI speaker system to support hands-on science lab, where\nit complements the auditory learning channel to the lab that\ntypically utilizes the other three.\n4) Multimodal Assessment: Given the multimodal nature of\nlearning, assessments should use multimodal evidence to better\ncapture how students apply their knowledge to solve problems.\nTraditional assessments had primarily focused on factual knowl-\nedge, often using formats, such as multiple-choice questions,\nwritten explanations, essays, or short answers [22]. However,\nassessments that rely on a single mode of representation, or\nmonomodal assessments, have limited capacity to capture stu-\ndent thinking [23], [24]. In contrast, multimodal assessments\nbolster construct validity by aligning more closely with the\nmultifaceted nature of learning. These assessments more accu-\nrately measure what they intend to assess [25], thereby enhanc-\ning the credibility and accuracy of the assessment. Moreover,\nmultimodal assessments foster increased engagement among\nstudents. In addition, given students’ different preferences for\ninformation channels, multimodal assessments facilitate educa-\ntional equity and diversity [26].\nRecently, assessments have been evolving to encompass var-\nious modes, such as written responses, visual images, and in-\nteractive elements, encouraging multifaceted modes of student\nexpression and comprehension. For example, the Next Genera-\ntion Science Standards emphasize engaging students in scientiﬁc\npractices throughout multimodal science assessment [27].A l s o ,\nthe Programme for International Student Assessment utilizes\nwritten texts and illustrations to present natural or social phe-\nnomena, prompting students to represent their ideas in various\nmodes.\nMoreover, advances in computer and digital technologies\nhave facilitated the collection of multimodal responses to assess-\nment tasks [28]. For example, Zhai et al. [29] asked students to\ncreate a drawn model and provide a written explanation of their\nmodel on a computerized platform. Du et al. [30] adopted a\nmultimodal analysis of college students’ collaborative problem-\nsolving in computer networks. These imply that the convergence\nof multimodal assessments and AGI holds immense potential for\nrevolutionizing assessments.\nB. Multimodality in AGI Agent\n1) Essential Components of AGI: AGI refers to a form of\nintelligence that can understand, learn, and apply knowledge\nin a general, human-like manner, capable of performing various\nintellectual tasks [5]. The development of complex AGI systems\ndepends on various cognitive processes, learning capacities,\ndecision-making abilities, and adaptation strategies AGI [31].Authorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 669\nThe distinctive components of AGI compared to ANI are\nsummarized as follows.\nConstructing Cognitive Frameworks:All-encompassing AGI\nsystems incorporate cognitive processes, such as reasoning,\nlearning, memory, and perception. This allows AGI systems to\nimitate human cognitive processes by modeling the structural\nand functional principles of the human mind [32].\nRepresentation and Manipulation of Knowledge: This entails\naccumulating knowledge about the world, applying logic, mak-\ning deductions, and updating it with fresh experiences [33].\nTechniques, such as logical reasoning, probabilistic models,\nsemantic networks [34], and knowledge graphs [35], [36],a r e\nused for this purpose.\nAdaptive Learning Capabilities: AGI needs to be ﬂexible\nand experience-based. This entails employing machine learning\nmethods, such as deep reinforcement and unsupervised learning,\nto change behavior and enhance performance [37].\nStrategic Planning and Decision-Making: For AGI systems\nto accomplish tasks and solve challenging issues, they must be\ncapable of advanced planning and decision-making. Plans are\ncreated using search algorithms, optimization, and game theory\nto achieve desired results [38], [39].\nLanguage Processing and Interaction: For AGI to process\ninformation and communicate with people efﬁciently, it must\ncomprehend and produce human language. For this, natural lan-\nguage processing (NLP) techniques, such as discourse analysis,\nsemantic analysis, and syntactic analysis, are applied [40], [41].\nIntegrating Multimodal Data: Text, image, video, and audio\nare just a few sources AGI systems have to handle [42], [43].\nEffective decision-making in AGI requires extracting and syn-\nthesizing information from multimodal inputs.\nAmong these foundational principles, in this article, we put\nextra focus on the multimodal nature of AGI that contrasts with\nthe traditional and unimodal notion of ANI.\n2) Multimodal AGI V ersus Unimodal ANI: AGI and ANI\nrepresent two distinct paradigms in AI. While AGI aims a\nhuman-like comprehensive reasoning ability [5], In contrast,\ntraditional ANI, also known as “weak AI,” is specialized in a\nspeciﬁc task or ﬁeld and lacks the general cognitive abilities[44].\nMultimodality, the ability to process and integrate multiple\ndata types, is a key area where AGI and ANI differ signiﬁcantly.\nAlthough early pioneers of AGI systems, such as GPT-3 and\nChatGPT, can handle only one modality, many recent multi-\nmodal AGI systems, such as KOSMOS-2 and GPT-4V , were\ndedicated to handling various data modalities, mimicking the\nhuman brain’s ability to process various sensory inputs [45],\n[46], [47]. This capability allows AGI systems to perceive the\nenvironment holistically, leading to a more sophisticated under-\nstanding and decision-making.\nMoreover, leveraging pretraining on extensive multimodal\ndatasets and advanced reasoning capabilities of large language\nmodels (LLMs), newly released AGI models exhibit emergent\nabilities in processing previously unseen data [48], aligning\nclosely with human zero-shot and few-shot learning capabilities.\nThe multimodality of AGI systems signiﬁcantly enhances inter-\naction with the environment following human instructions [49].\nThis scalability starkly contrasts the rigid, task-speciﬁc\nfunctionality of ANI systems, which are optimized for particular\napplications but generalization to new contexts [50].B yt h i s\nmultimodal integration, AGI can make more informed and ac-\ncurate decisions than ANI [31], which is appreciated in dynamic\nenvironments where the ability to quickly adapt and respond to\nnew information is crucial.\n3) Multimodal AGI as Educational Agent: In the traditional\ndeﬁnition of AGI, emulating human intelligence and problem-\nsolving abilities was central [51]. However, in educational set-\ntings, the focus moves to how AGI can interact with teachers\nand students to enhance their educational experiences [45],\n[51], [52], [53] Consequently, a wider variety of learners can\naccess and beneﬁt from multimodal AGI educational agents\nbecause each mode of interaction provides a unique point of\nentry for learning. It can be best achieved when multimodal\neducational AGI collaborates with human educators, enhancing\ntheir pedagogical approaches. Therefore, recently, multimodal\nAGI has been understood as an educational agent that can\nsupport teachers and students in classrooms [54], [55].\nThe potential of multimodal AGI as an educational agent is\nderived from its unique characteristics. First, AGI’s conversa-\ntional affordance makes it capable of interacting with instruc-\ntors and learners in natural language [54], [55], [56], enabling\nthem to consult high-performing AI models without technical\nexpertise. Second, the multimodal nature of AGI resembles\nand supports human multimodal learning [57], enabling it to\nconvey multimodal information digested for human learners.\nThird, multimodal AGI systems adapt to different teaching and\nlearning situations and meet students’ individual needs in terms\nof learning modality [50].\nAs multimodal AGI is grounded on its reasoning ability that\nemerges from a vast amount of training data with multiple\nmodalities [48], it provides unique affordances compared to\nexisting educational technologies, such as intelligent tutoring\nsystems, adaptive learning platforms, and traditional AI tools.\nIt is true that they have shown success in personalizing in-\nstruction and supporting speciﬁc learning outcomes to some\nextent. However, they often rely on preprogrammed scenarios\nand structured domain models provided by developers [21].\nEven traditional AI tools simply mimic the mapping function\nbetween the input and output, which is given as ground truth by\na user, lacking the ability to dynamically integrate or generate\nmultimodal content [58].\nIronically, multimodal AGI’s broad probabilistic reasoning\nability also raises challenges in explainability, consistency, and\nalignment with curricular standards. In addition, AGI’s re-\nliance on large-scale computational infrastructure distinguishes\nit from lightweight, domain-speciﬁc AI tools optimized for\nlocal deployment. Some of these challenges are addressed in\nSections VII and VIII.\nSeveral pioneering studies showcased the potential of\nmultimodal AGI agents applicable to concrete educational\nsituations. Sharma et al. [4] collected university students’\neye-tracking, electroencephalography, facial video, and arousal\ndata from wristbands while the participants were engaged in\nonline adaptive self-assessment for a Web Technologies course.\nThey showed that fusing eye-tracking, facial expressions,\nand arousal data best predicts the students’ effort and\nperformance in the assessment [4]. Cukurova et al. [59]\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n670 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nFig. 4. Overview of modalities of AGI for education as part of multimodality.\nexamined how multimodal data fed to AI can help expert tutors’\ndecision-making in evaluating the debate skills of candidate\ntutors. They showed that the AI model trained with the combined\ndataset on the candidate tutors’ personal characteristics and\naudio records was most successful in predicting expert tutors’\nevaluations of them. Meanwhile, for science education,\nBewersdorff et al. [60] showed that multimodal AGI, such\nas GPT-4V , can be fed with image data to 1) elicit learning\ncontent from graphical representations, 2) guide students with\ninquiry steps with the given material, and 3) support students’\npresentations across tabular data, diagram, and text.\nAccording to Bewersdorff et al. [60], multimodal AGI for\neducation supports transforming content from one modality to\nanother and shifting from unimodality to multimodality in learn-\ning. Therefore, further establishing a synthetic understanding of\nmultimodal AGI for education requires a thorough understand-\ning of how various modalities serve student learning.\nIII. T EXT MODALITY IN AGI FOR EDUCA TION\nIn SectionsIII–VI, we examine how various modalities in AGI\nsystems support student learning. The overview of the sections\nis presented in Fig. 4.\nA. Text Modality in Education\nText combines characters and symbols to transfer, store,\nsynthesize, and analyze information [61]. “Text” in education\nincludes many materials, such as textbooks, scholarly articles,\ndigital content, interactive media, and various other written\nformats [62], which is not only a fundamental part of education\nbut also serves as a primary medium of acquiring knowledge\nand developing critical thinking skills [63].\nB. Technical Backgrounds of Text Analysis and Generations\nBefore LLMs, recurrent neural networks [64] and attention\nmechanisms were popular for NLP tasks. The Transformer\narchitecture marked a signiﬁcant leap forward [65]. Bidirec-\ntional encoder representations from Transformers [66] further\nrevolutionized NLP by understanding the surrounding context\nof words. LLMs, such as OpenAI’s GPT-4 [1], have scaled\nthis concept, showing that the effectiveness often increases with\nmodel and training corpus size.\nA standard transformer has two main components: an encoder\nand a decoder. The encoder processes the input data, and the\ndecoder generates the output. However, the generative pretrained\nTransformer (GPT) series, including ChatGPT/GPT-3.5 [67]\nand GPT-4 [1], are decoder-only generative language models\nthat primarily focus on text generation tasks.\nLLM’s inner architecture enables generative language models\nto effectively capture and leverage complex patterns and depen-\ndencies in data. For instance, GPT-3 has 175 billion parameters,\npushing the limits of text generation capabilities and handling\ncomplex tasks, such as translation and question-answering.\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 671\nNon-GPT language models, such as PaLM-2 [68] and the\nLLaMA series [69], also experienced similar success.\nThe release of ChatGPT in November 2022, a conversation-\nfocused model that follows human instructions, further under-\nscored the feasibility of AGI in practical applications [70].\nGPT-4, the most recent iteration, is the most powerful LLM\nto date. This progression in the GPT series not only reﬂects the\nrapid advancements in AI and NLP but also underscores the\nincreasing importance of these technologies in education.\nC. Educational Applications of AI for Text Modality\n1) F or Assessment and Feedback: Assessment is a signiﬁcant\ninﬂuencing factor for effective learning[71], especially in forms\nof (computer-based) “rapid formative assessment” [72].A G I -\ndriven systems could potentially transform assessment practices\nand help teachers build on this feedback [73].\nLLM-based AGI systems can assist users in their writing\nprocess [74]. More speciﬁcally, ChatGPT can help improve\nwriting skills from a very young age to professional writing[75].\nAGI systems, such as the PEER system [76], can assist the\nteacher with assessment and providing feedback on a massive\namount of student’s essays. This contrasts with previous studies,\nwhere comprehensive feedback was not always available. LLMs\ncan also automatically identify student errors in their science\nexperiment protocols reliably and validly [77] to provide indi-\nvidualized feedback and streamline assessments.\n2) F or Content Curation and Creation: Finding or devel-\noping suitable learning opportunities for students is the foun-\ndation of every learning process. High-quality learning tasks\nenable teachers to formatively diagnose student conceptual un-\nderstanding and difﬁculties, monitor progress, and evaluate the\nefﬁcacy of pedagogical methods. LLMs can create exercises\nwith sample solutions and complementary guiding materials and\nexplanations. AGI-driven applications can help teachers create\nlearning tasks [78] or multiple-choice questions [79] to support\nstudent learning through formative assessment. This can lead to\npersonalized and adaptive learning.\n3) To Stimulate Affective Domains: Developing and main-\ntaining learning motivation [80] and curiosity [81] are essential\nprerequisites for learning. Abdelghani et al. [54] explored using\nGPT-3 to stimulate children’s curiosity and improve their ability\nto ask questions. They developed a system that automatically\ngenerates prompts designed to encourage children to ask more\nand more profound questions. Silitonga et al. [82] also demon-\nstrated the role of LLM-based learning in boosting students’\nmotivation for English writing. They observed that text-based\nAI chatbots offer more prosperous and nuanced feedback than\nteachers alone, motivating students to engage more deeply with\ntheir learning.\n4) To Improve Peer Assessment: Peer assessment is a process\nby which students give feedback on another student’s work based\non a rubric provided by the instructor [83]. Results indicate\nthat peer assessment is more effective than teacher assessment\nand remarkably robust across a wide range of contexts [84].\nAGI-driven systems can comprehensively and automatically\nevaluate the quality of peer review comments to improve peer\nassessment [85].\nIV . IMAGE MODALITY IN AGI FOR EDUCA TION\nA. Image Modality in Education\nImage plays a critical cognitive role in learning, as it interacts\nwith learners’ visuospatial ability[86]. As reviewed earlier, ana-\nlyzing student-drawn images in multimodal assessment provides\nsophisticated information about students’ understanding of the\nlearning content. Also, visualizations have been widely used in\npedagogies for various subjects, such as mathematics, reading,\nand science [87].\nB. Technical Backgrounds of Image Analysis and Generations\n1) Image Classiﬁcation: Image classiﬁcation is a fundamen-\ntal task in computer vision that teaches machines to categorize\nimages into one of several predeﬁned classes. Traditionally, a\ndual-stage approach was used to solve the classiﬁcation prob-\nlem [88]. Handcrafted feature extractors were ﬁrst applied to\nimages, and the extracted features (e.g., shape and texture)\nserved as inputs to a trainable classiﬁer using machine learning\nalgorithms.\nAfter the development of the convolutional neural network\n(CNN), image processing technology faced a huge turn. CNN\nreceives 2-D pixel data, usually comprising three color layers\n(red, green, and blue) as input. CNN models typically consist\nof convolutional layers, pooling layers, and fully connected\nlayers [88]. They automatically extract relevant features from\nimages through convolutional and pooling operations, reducing\nthe need for handcrafted feature extraction. Nowadays, typical\nimage processing pipelines use CNN layer modules.\n2) Visual Question Answering: Visual question answering\n(VQA) was introduced by Antol et al. [89] as a new problem\nthat advanced multimodal AI should be able to solve so that the\nmodel could be evaluated by it. Antol et al. [89, p. 2425] deﬁned\nthat “VQA system takes as input an image and a free-form,\nopen-ended, natural-language question about the image and\nproduces a natural-language answer as the output”. For example,\nan AI model is given an image and a user query, such as “Does\nthis man have children?” “what kind of cheese is topped on\nthis pizza?” and “How many glasses are on the table?.” Then,\nthe model could answer, such as “yes,” “mozzarella,” and “6”\n[89]. To solve these open-ended VQA tasks, the multimodal\nAI should be able to make text-based Q&A and describe visual\ncontent, which requires the integration of computer vision, NLP ,\nand knowledge representation and reasoning. The release of\nvision language models (VLMs), such as GPT-4V(ision) and\nGemini, has dramatically improved broader users’ access to\nVQA techniques [90].\n3) Image Generation: Image generation models [91] have\nbecome increasingly popular, especially after the development\nof generative adversarial networks (GANs) [92]. The recent\nsuccess of various large generative AI models, such as DALL ·\nE [93], Imagen [94], and Stable Diffusion [95], also fosters the\nwide acceptance of generative AI of images among the general\npublic. There are three typical image generation model types.\n1) Likelihood-based generative models, such as autore-\ngression models [91] and variational autoencoders [96],\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n672 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\ndirectly model the data likelihood to efﬁciently generate\nnew images based on a pretrained model.\n2) In likelihood-free generative models [97], the probability\ndistribution of data is implicitly represented by sampling\nprocesses. For example, GANs [92] use two intertwined\nneural networks—the generator and the discriminator. The\ngenerator generates new data samples (e.g., images and\ntexts) given some conditions, such as class labels. The\ndiscriminator aims to distinguish data samples generated\nby the generator from the real data samples. Two com-\nponents are trained adversarially within a minimax game\nframework.\n3) Score-based generative models (SBMs) [98] estimate the\nscore function with respect to the data probability density.\nThese models are sometimes called diffusion models.\nSBMs include Imagen, DALL· E-2, and Stable Diffusion.\nC. Educational Applications of AI for Image Modality\n1) Image Classiﬁcation: Image classiﬁcation models have\nbeen used to automatically score student-generated images[29],\n[58], [99]. V on Davier et al. [100] adopted artiﬁcial neural\nnetworks to classify graphical responses from a TIMSS 2019\nitem. They found that CNNs outperform feed-forward neural\nnetworks in classiﬁcation accuracy comparable to human raters.\nZhai et al. [29] used ResNet-50 V2 CNN to develop scoring\nmodels for students’ free-drawn modeling tasks. Lee et al. [58]\ndeveloped a method employing instructional notes and rubrics\nto prompt GPT-4V to score students’ drawn models for science\nphenomena.\n2) Visual Question Answering: Aishwarya et al. [101] tech-\nnically showed that their VQA model achieved 67.15% accuracy\non queries for textbook illustrations. Similarly, Gupta et al.[102]\nsuggested that students could learn themselves using the VQA\nsystem with textbook illustrations—for example, an elementary\nstudent could ask a model, “What kind of animal classes can be\nseen in this image?” and the model returns, “mammal”. Suresh\net al. [103] used VQA to gamiﬁcation of early learners’ (3–4\nyears old) word learning by developing a system that asks a user\nto answer whether a presented image is an “animal” or a “sport”\n(Level 1) or which animal or which sport (Level 2). Recently,\nLin [104] suggested that VQA models with higher performance\ncould beneﬁt college students learning English, Mathematics,\nand Chinese.\nLee and Zhai [105] showed that GPT-4V successfully re-\ntrieves problem context and human evaluators’ scoring examples\nin the image and evaluates student-drawn models for chemical\nreactions. As a result, they reported that GPT-4V’s average\nscoring accuracy was 51% for the trinomial image classiﬁ-\ncation task according to students’ learning progression—i.e.,\none of “Proﬁcient,” “Developing,” and “Beginning,” which is\npromising but falling behind the typical accuracy threshold of\n90% for scoring machines. The abovementioned Bewersdorff\net al.’s work is also relevant to VQA [60].\nRecently, Lee and Zhai [90] again showed how VLMs, such\nas GPT-4V , could be used for education, realizing VQA. With\nexample qualitative analyses on the ChatGPT user interface for\neach, they showcased that VQA can be used for 1) eliciting\napplications of intriguing images, 2) analyzing instructor’s ped-\nagogical practice, 3) analyzing learners’ engagement, 4) assess-\ning learner-generated visual data, and 5) assessing classroom\nresources and environments.\n3) Image Generation: Image generation is a novel ﬁeld in\nan educational context. Likelihood-free generative models, such\nas GANs, have been shown to be effective in generating high-\nquality synthetic images. For example, Ali et al.[106] introduced\nGANs to middle school students to teach how modern AI works,\nwhere students generated fake but realistic graphics with web-\nbased tools. Also, SBMs, such as Stable Diffusion, have been\ndeemed to be useful for generating image materials for visual\narts education [107] or children’s storybooks[108], and DALL·\nE series for gifted [109] and medical education [110]. These\nattempts suggest the wide applicability of graphic generation\nfor various subjects.\nV. A UDIO ANAL YSIS ANDGENERA TION IN EDUCA TION\nA. Audio Modality in Education\nAudio modality covers spoken words and music as a fun-\ndamental channel of communication for teaching and learn-\ning [111]. This encompasses various formats and technologies,\nfrom traditional methods, such as lectures and radio broadcasts,\nto modern digital audio formats, such as podcasts, audiobooks,\nand educational apps. While audio modality may be considered\nmost signiﬁcant in language learning, other subjects, such as\nscience, also beneﬁt from audio modality [112]. Educational\nscholars have recorded and analyzed audio data to understand\nclassroom discourse spoken by teachers or students, which\nreveals the sophisticated interactions among participants [113].\nB. Technical Backgrounds of Audio Analysis and Generation\n1) Audio Analysis: Audio analysis is widely supported by AI\ntechnology, and it includes speech, voice, music, and environ-\nmental sound recognition. Analysis of human speech involves\ntwo steps. First, speech-to-text (or speech recognition) tech-\nniques are used to convert audio to text. Second, the transcribed\ntext data are processed by the inner AI module. In speech-to-text\ntechniques, various feature extraction methods are used based\nupon the wave’s characteristics, such as waveforms, spectro-\ngrams, and mel-frequency cepstral coefﬁcients[114]. While var-\nious CNN models are used to analyze the audio 2-D data (wave-\nform versus time), Fourier transform techniques are frequently\nused [115] to eliminate the surrounding noise. Once the speech is\nconverted to text, the inner module of the AI engine can process\nthe text data for various purposes, which essentially corresponds\nto NLP techniques. Similar to the strength of AI chatbots, AI\nspeaker applications tend to identify certain predeﬁned words\nin user speech to capture the user’s intention [21],[116].\n2) Audio Generation: Audio generation techniques focus on\ntext-to-speech generation (or speech synthesis). Once input text\nis received, it is preprocessed, phonetic analysis and grapheme-\nto-phoneme conversion are conducted to retrieve the speech\ndatabase, speech units are concatenated, and the waveform is\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 673\ngenerated [117]. The deep learning architectures used for au-\ndio generation include autoencoders, GAN, normalizing ﬂow,\nTransformer networks, and diffusion models [118]. WaveNet\nis a foundational autoregressive algorithm for implementing\nvocoder (token-to-speech synthesizer) [119]. However, GAN-\nbased vocoders, particularly HiFi-GAN [120], are most fre-\nquently used in recent studies as it is fast and successful in\nsynthesizing high-ﬁdelity speech [121].\nSome AI services that both analyze and generate audio. For\nexample, AI speaker services, frequently combined with conver-\nsational agents mounted on mobile applications (e.g., Amazon\nAlexa, Apple Siri, Samsung Bixby, OpenAI ChatGPT), support\nexplainable interfaces based on users’ utterances.\nC. Educational Applications of AI for Audio Modality\n1) Audio Analysis: Audio analysis based on AI mainly tar-\ngets learners’ voices. James et al.[122] indicated the potential of\naudio recordings for automatically predicting classroom climate\nby developing a system to detect speakers and social behavior\nand infer classroom climate from nonverbal features. Canovas\nand Garcia [123] developed an automated classroom audio\nanalysis system that can distinguish the speakers’ identities\nwhen there are multiple speakers simultaneously. Based on\nthe audio information, they derive nonverbal features that can\ndescribe patterns and classify the different activities and teaching\nmethods. Cosbey et al. [124] introduced a set of deep learning\nclassiﬁers designed for automatic classroom activity annotation.\nThe deep learning classiﬁers analyze classroom recordings and\ncategorize frames into “single-voice,” “multivoice,” “no-voice,”\nor “other,” thereby quantifying different types of classroom\nactivities. Reddy and Chen’s [111] study on “Audio Classiﬁer\nfor Endangered Language Analysis and Education” examines\ntwo crucial aspects of their application: the audio classiﬁer and\nlanguage learning. The audio classiﬁer is adept at automatically\nidentifying vowels and consonants in Blackfoot audio ﬁles, facil-\nitating user access to these linguistic elements. Simultaneously,\nthe language learning component of the application allows users\nto examine the pitch patterns of these instances visually.\n2) Audio Generation: Educational applications of audio gen-\neration are typically found in AI speakers adopted for instruc-\ntional situations. For example, AI speakers have been proposed\nto help provide timely information to learners [21], [125].A I\nspeakers are especially helpful in supporting students with\nspecial educational needs as they become social partners or\nfacilitating language learning as they help learners have ver-\nbal conversations [125]. Notably, studies have suggested that\npersonalized voices from AI speakers could reduce learners’\npsychological distance from AI [116], [125]. There have been\nattempts to integrate AI speakers into authentic instructional\nsituations. Lee et al. [21] developed the AI-speaker system that\nverbally responds to students to calculate the number of needed\nreagents, recall experimental procedures, and determine where\nto dispose of liquid wastes. Lee et al. [116] also implemented\nAI speaker-based learning modules that shape collaborative\nlearning between human learners and AI speakers in small\ngroups to co-construct their knowledge in the zone of proximal\ndevelopment.\nVI. V IDEO ANAL YSIS ANDGENERA TION IN EDUCA TION\nA. Video Modality and Education\nVideo analysis techniques can be applied in various educa-\ntional settings, from K-12 to higher education and professional\ndevelopment [126]. Video can capture the complexities inherent\nin teaching and learning. Allowing detailed examinations of\nteaching and learning from multiple and different perspectives,\nthere has been a notable increase in the use of video as a tool\nfor analyzing classroom dynamics [127]. Meline et al. [128]\nconducted a meta-analysis to evaluate the effectiveness of video\nanalysis in improving teacher outcomes and underscored the\npotential of video analysis as a promising practice, particularly\nin enhancing praise and implementation strategies in teaching.\nB. Technical Backgrounds of Video Analysis and Generation\n1) Object Detection and Video Analysis: Object detection in\na real-time ﬂow of images can be considered a basic form of\nvideo analysis. Object detection “deals with detecting instances\nof visual objects of a certain class (such as humans, animals,\nor cars),” solving the problem of “ what objects are where ?”\nin the given image ( [129, p. 257] ; italic as in original). As\nwith other machine learning ﬁelds, object detection has also\ndeveloped with current deep neural network-based algorithms—\nparticularly CNN—since the 2010s [130]. For example, Y ou\nOnly Look Once [131] is one of the ﬁrst algorithms that enabled\nreal-time object detection even on mobile smartphones, and its\naccuracy is constantly increasing.\nReal-time object detection is connected to object tracking in\nvideo. Once images of a person are fed to a video analysis\nmodel, they can be analyzed in terms of gesture, emotion,\naction, interaction, group activity, and others as needed [132].\nParticularly, neural networks that process temporal information,\nsuch as Recurrent-CNN and 3-D CNNs, are used [132].\n2) Video Generation: Since video can be understood as a set\nof consecutive images (frames) that show continuous changes,\nvideo generation techniques rely on similar neural network\nmodels built on CNN modules as image generation techniques\ndo. However, the video modality should additionally maintain\nspatiotemporal consistency and adhere to real-world physical\nprinciples [133], [134]. Models, such as GAN, autoregressive\nmodels, and diffusion models, are used under “divide and con-\nquer” and “temporal autoregressive” paradigms to achieve these\ngoals in video generation tasks [134].\nRecently, user-friendly video generating models, such as Ope-\nnAI’s Sora[135] and Meta’s Movie Gen[136], have revolution-\nized how video content is generated. Any user can generate short\nvideos from their text prompts (text-to-video) or example images\n(image-to-video). Those services further support revising the\nvideo based on the timeline-based storyboard, maximizing its\nusability.\nC. Educational Applications of AI for Video Modality\n1) Object Detection and Video Analysis: Studies have sug-\ngested adopting object detection and video analysis for educa-\ntional studies. Many demonstrated that these techniques can be\nused to recognize students’ face, activity (e.g., hand raising,\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n674 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nsleeping, attention, etc.), and emotion in classrooms [137].\nHowever, most applications of object detection have been ex-\nploratory, and only a few studies have reported their perfor-\nmance metrics other than detection frequency [138], [139].\nNotably, Sun et al. [140] developed the phygital (physics +\ndigital) curriculum-inspired board game for kids aged 5–8. In\nthe game, students could manipulate wooden blocks to assemble\nvarious polygons, and then the camera detected and predicted\nstudent-assembled polygons almost perfectly (F1 ≥ .99).\nMore sophisticated automatic video analysis was employed in\neducation. V an der Haar[141] captured video of classroom situ-\nations, preprocessed it, and automatically classiﬁed the students\ninto different emotion categories. Sahla and Kumar [142] sug-\ngested a system for assessing classroom teaching by analyzing\nand classifying student mood. Lee et al. [143] combined deep\nlearning and computer vision in an automated STEM activity\nbehavior recognition system to aid in understanding students’\nlearning processes in STEM activities. Ramakrishnan et al.[144]\npresented a multimodal automatic classroom observation system\nto analyze videos of classrooms for the climate, based on inte-\ngrating information including audio, the faces of teachers and\nstudents, and the pixels of each image frame. On the other hand,\nBenedetto et al. [145] focused on optimizing lecture content\nsummarization in their study, which overcomes the limitations\nof traditional extractive models. This method can generate more\nreadable and coherent summaries of lecture content, proving to\nbe a valuable tool in enhancing the accessibility and efﬁciency\nof learning materials for students.\n2) Video Generation: Several studies have suggested how\nvideo generation technologies could be used for education.\nKumar et al. [146] introduced CCVS, DreamPose, and Fast\nVid2Vid for potential cutting-edge video generation models,\nwhich can serve for innovative visual storytelling. Weerakoon\net al. [147] showed that ChatGPT, DALL · E, and Narakeet\ncan be used to generate instructional videos based on course\ndescription. Dao et al. [148] also reported that they generated\nlecture videos based on text-to-speech and speech-driven-face\ntechniques. Meanwhile, Contreras et al. [149] also reported that\nAI-generated videos were implemented for continuing medical\neducation. In total, 25 learners were satisﬁed in terms of the\nvideos’ quality, engagement, and pace for learning, while only\n32% of them noticed these were generated by AI [149].\nHowever, there was a limited number of studies that uti-\nlized video generation for educational purposes. Future attempts\nshould embrace the potential of AGI for education, which can\neven generate the most advanced form of multimodal represen-\ntation of reality.\nVII. E THICAL USE OF AGI IN EDUCA TION\nWhile educational AGI presents a transformative affordance\nto analyze and generate multimodal content, it also introduces\ncomplex challenges. Latif et al. [150] emphasized the emerging\nethical issues associated with AGI in education and its ability to\nreproduce and replicate human capabilities. Expanding on Latif\net al. [150], we suggest that the implementation of educational\nAGI must aim at a commitment to data privacy and ethical\nintegrity, system explainability, transparency, and fairness, and\nresponsible deployment and decision-making. The overview of\nthis section is presented in Fig. 5.\nA. Ethics of AI\nEthical use of AGI in education, as a particular aspect of AI\nethics, can be established upon both the ethics of AI in general\nand in education.\n1) Ethics of AI in General: The growing ubiquity of AI\nacross all sectors of society has given rise to the emergence of\ncomplex ethical dilemmas and derived scholarly discussions.\nThe discourse on AI ethics has been thoroughly examined\nin seminal works [151], highlighting its multifaceted nature.\nA critical aspect pertains to data ethics, including the chal-\nlenges of bias, data privacy, decision-making, and transparency\nthroughout the data lifecycle [152]. Furthermore, the ethical\nlandscape of AI extends to the socioeconomic impacts of AI,\nsuch as employment displacement and the need for workforce\nretraining [153], which could widen social inequalities [154].\nEncapsulating those concerns, the Montreal Declaration for re-\nsponsible AI proposes a general human-centered framework for\nAI ethics [155], promoting principles, such as autonomy, well-\nbeing, personal privacy, solidarity, democratic participation,\nresponsibility, equity, diversity, prudence, and sustainable de-\nvelopment. For example, high-stakes workforce domains, such\nas healthcare and criminal justice, confront signiﬁcant ethical\nissues pertaining to AI’s role in human decision-making, under-\nscoring the importance of responsibility and transparency[156].\n2) Ethics of AI in Education: Ethics has also received great\nattention in the ﬁeld of AIEd. Concerns about the large vol-\numes of data collected for learning analytics, such as student\nperformance data and detected emotional states through facial\nexpression and eye-tracking, are of critical focus [157].I nt h i s\nregard, it is imperative for researchers, educators, and policy-\nmakers to critically consider the following questions. 1) How\nshould the student data be analyzed, interpreted, and acted upon?\n2) How should the biases of decision-making be prevented or\nameliorated when considering gender, age, race, and family\nsocial status?\nThe AIEd ﬁeld further examines various issues, such as 1)\nthe access to education (e.g., educational fairness and equity to\nall students), 2) the roles of AI with respect to teachers (e.g., to\nreplace or augment human roles), and 3) the purpose of using\nAI in learning (e.g., help the student pass exams or prepare for\nfuture AI-empowered workforce). The question about student\nagency [158] is also posed about when students, for example,\nfollow AI tutors in personalized learning.\nStudies also discussed AI-enhanced tools and learning envi-\nronments. For example, researchers in AI-enhanced e-learning\nare interested in investigating ethical issues, such as user consent,\nequity and diversity, accessibility, identity and conﬁdentiality,\nand student privacy [159]. Regarding student privacy, Anwar\nand Greer [160, p. 63] posited that “when an observer [e.g.,\nan automated system] monitors students’ behaviors with full\nknowledge of their identity and performance, the student being\nmonitored does not enjoy any privacy”. In addition, the ethical\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 675\nFig. 5. Overview of ethical use of AGI in education.\npractices of students, such as cheating and plagiarism [161],a r e\nalso of scholarly focus. Similarly, researchers and technology\ndevelopers of intelligent agents focus on transparency, privacy,\nand fairness [162].\nB. Ethics of AGI in Education\n1) Data Privacy and Ethical Integrity in Educational AGI:\nEducational AGI systems rely on extensive data collection,\nincluding student academic records, behavioral patterns, and\neven personal biometric information. AGI models trained on this\ndata generate human-like content, potentially revealing sensitive\ninformation and/or confusing the correct attribution.\nTo protect student data for data privacy, the European Com-\nmission’s Ethical Guidelines on the Use of Artiﬁcial Intelligence\nand Data in Teaching and Learning for Educators emphasize\nthe importance of ensuring accountability in using student data\nto train and ﬁne-tune LLMs [163]. Clear policies must be\nimplemented that outline data usage, ensuring that students\nand parents fully understand the implications of AI-driven\ndata collection. The Data Ethics Framework for AIEd high-\nlights the need to implement robust data protection measures,\nincluding encryption and distributed data storage, to mitigate\nthese risks [163].\nFailure to secure data privacy can lead to data leakage,\nwhich raises the issue of plagiarism, a long-discussed topic\nin the educational community. Plagiarism is deﬁned as “the\nact of imitating or copying others’ creation or idea without\npermission and presenting it as one’s own” [164, p. 5] .T h e\nintegration of AGI systems, such as ChatGPT and Bing AI, has\nmarkedly intensiﬁed the ongoing discussion on its impact on\nacademic integrity when utilizing AGI on tasks, such as essay\nwriting [165]. Therefore, it is critical to reevaluate the existing\neducational integrity guidelines and call for innovative methods\nto detect and verify the originality of student work. Cotton\net al. [166] and Bissessar [167] also posited that various AGI\ntools, such as ChatGPT, not only offer beneﬁts, such as increased\nstudent engagement and collaboration, but also raise concerns\nregarding academic integrity and plagiarism. Accordingly, with\nthe increasing adoption of LLMs and AGI by students for\nwriting academic papers and completing various assignments, it\nis critical to develop effective detection systems for AI-generated\nresponses [168].\nExpanding on the ethical concerns regarding AGI-generated\ncontent in educational settings, the issue of AI credit and copy-\nright when students use AGI tools for their assignments becomes\nincreasingly complex. This ethical issue concerns the attribution\nand appreciation of work created through AI. According to\nLebenswissenschaften [169], the use of AGI in facilitating stu-\ndent assignments blurs the lines of intellectual property, forming\na gray area in deﬁning authorship and originality and leading\nto potential conﬂicts in academic integrity policies. Akgun and\nGreenhow [159] called for educational institutions to develop\nclear guidelines that delineate the acceptable use of AGI in\ncompleting academic assignments, ensuring that students under-\nstand the importance of original thought and effort. In addition,\nFoltynek et al. [170] suggested renewing academic policies to\nincorporate the nuances of AGI-generated content and grant the\ncopyright and credit to AI.\nFurthermore, although learners are increasingly using LLMs\ncapable of producing high-volume human-like texts to create\ncontent, in some instances, they generate compelling but mis-\nleading information [171]. For example, Galactics, an LLM\nfor science that can summarize academic papers, solve math\nproblems, and generate Wiki articles, was found to generate\nbiased and even incorrect results, such as generating fake papers\nand attributing references to real researchers [172], thus was\ntaken down soon after its release by Meta. Likewise, as ChatGPT\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n676 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nfurther brought LLMs into public sections, including educa-\ntion, it was criticized for biased or false outputs [173].T h e\ndeployment of LLMs and AGI for generating misinformation\nis detrimental to learners’ accurate understanding of domain\nknowledge and concepts, especially considering that many lack\nthe proactive abilities and awareness necessary to identify AGI-\ngenerated misinformation.\n2) Explainability, Transparency, and Fairness in Educational\nAGI: The rapid advancement of AGI in educational settings\nhighlights the critical need for enhanced explainability and trans-\nparency in AGI models and mechanisms to ensure their unbiased\nand fair application in addressing educational challenges for all\nstudents [174].\nExplainability refers to the capacity of an AGI system to\nelucidate its thought processes in a manner comprehensible to\nusers. In educational settings, where AGI models are tasked with\nprocessing sensitive data, such as student responses, the explain-\nability of their thought is profound, inﬂuencing teachers’ instruc-\ntional decisions and practices[175]. For example, in multimodal\nassessment where AGI models are responsible for analyzing\nand assessing various modes of student responses, the need for\nexplainability becomes even more imperative. Teachers, who are\nthe frontline enactors of AGI technologies, must understand the\nrationale behind the AI’s analytic and generative processes, as\nwell as the criteria and algorithms it employs to integrate them\ninto their teaching strategies effectively [150], [176].\nTransparency involves the openness of an AI system regarding\nits functionalities and data usage. Transparent AGI systems dis-\nclose the types of data collected, the purposes of data utilization,\nand the methodologies employed in processing this information.\nThis openness is crucial in education, where stakeholders must\nbe assured that student data are handled responsibly and that the\nAGI’s operations are aligned with educational objectives. The\nEuropean Commission’s guidelines on the use of AI and data\nin teaching underscore the necessity for transparency to build\ntrust and allow decisions to be evaluated or challenged [163].\nMoreover, Wu et al. [177] highlighted the importance of in-\nterpretable machine learning models in fostering transparency,\nemphasizing the need for AGI systems that allow educators to\naudit and understand AI-driven decisions.\nFurthermore, fairness in the AGI system ensures that the\ndecisions are unbiased and inclusive, addressing imbalances\nin training data and preventing discrimination [178].I n\neducational settings, this means that AGI systems should\nprovide equitable learning opportunities, regardless of a\nstudent’s background[179]. Ensuring fairness involves critically\nassessing training datasets and algorithms to identify and\nmitigate potential biases. For example, Latif et al. [178] found\nthat models trained on a balanced dataset incorporating data from\nboth female and male students outperformed gender-speciﬁc\nmodels. This ﬁnding underscores the importance of diverse\ntraining data in mitigating biases and enhancing the fairness of\nAGI systems in educational decision-making.\n3) Responsibility and Decision-Making in Educational AGI:\nThe integration of AGI into education brings forth complex ques-\ntions about responsibility and decision-making. Dignum [180,\np. 1] described responsible AI as “about being responsible for\nthe power that AI brings”, which is about ensuring that the\nresults of the development and utilization of AI are beneﬁcial for\nmany. The main challenge of responsible AI is: who or what is\nresponsible for actions and decisions made by AI systems[180]?\nAI systems, even with some level of human-like intelligence, are\nartifacts that cannot be seen as actors to take the responsibility\nto determine and evaluate their behaviors and outcomes.\nThere are high-stakes educational situations where the matter\nof responsibility becomes critical. For example, what will hap-\npen if decisions for identifying at-risk students or accepting a\ncollege application are made by AGI systems? Is the developer\nof the algorithm responsible, and are the data providers or the\nusers who accepted AGI’s decisions? Answering those questions\nand distributing responsibility appropriately presents a complex\nchallenge, necessitating a shared approach that engages various\nstakeholders, such as AI developers, educators, policymakers,\nand researchers, through multiple stages of AI system develop-\nment and application. Moreover, AI-driven decision-making in\neducation introduces ethical and procedural dilemmas, as biases\nembedded in training data or algorithmic processes can dispro-\nportionately impact marginalized student groups. Recent studies\nsuggest that transparency in AI decision-making, explainable\nAI, and human-in-the-loop models are crucial for mitigating the\nrisks of unintended biases and ensuring that educators retain\nagency over critical educational determinations [177], [178].\nThe ethical issue of preserving human agency and autonomy\nis also increasingly discussed in the context of AGI adoption\nin education. Integrating AGI tools into educational practices\nrisks diminishing human decision-making, a fundamental aspect\nof learning and cognitive development. Prunkl [181] posited\nthat autonomy is a cornerstone of human dignity, making its\npreservation in the era of AI crucial. The potential of AGI to\nsupport and foster human autonomy is signiﬁcant, yet there are\nsubstantial risks, such as AI-facilitated deception and manipula-\ntion, which could seriously interfere with human autonomy on a\nlarge scale. Moreover, rapidly developing AI might replace the\nskills necessitated in various workforce areas, such as decision-\nmaking, critical thinking, creativity, teamwork, and communi-\ncation [182]. In addressing the issue surrounding human agency\nand autonomy, it is critical to balance the beneﬁts of AI in-\nnovation with the preservation of fundamental human values\nin shaping a future where technology serves as a tool/partner\nfor enhancing human capabilities rather than supplanting\nthem.\nEducators are responsible for equipping learners with the\ncritical thinking skills and digital literacy necessary to discern\nthe credibility of AGI-generated content. For instance, edu-\ncators can encourage learners’ skepticism and the question-\ning of sources provided by AGI to evaluate the trustworthi-\nness of AGI-generated content. The critical responsibility lies\nwith humans rather than AI systems. Furthermore, scholarly\nresearch has also focused on developing theoretical and prac-\ntical methods for identifying AI-generated misinformation. In\na recent study, Zhou et al. [171] investigated the distinct fea-\ntures of AI-generated misinformation by comparing them with\nhuman-created misinformation and introduced a theory-guided\ntechnique to detect such content effectively.\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 677\nC. Practical Implementation of Ethical AGI Frameworks in\nEducation\nSeveral educational institutions offer practical illustrations\nof how ethical frameworks for A(G)I integration can be suc-\ncessfully implemented in educational contexts. For example,\nStanford University’s Human-Centered AI initiative emphasizes\nhuman oversight, transparency, and privacy, advocating that AI\nsystems should augment rather than replace human agency in\nteaching and learning environments. Their approach includes\nclear guidelines on how AI tools can be used to augment, rather\nthan replace, human instruction, and mandates that students must\nbe informed whenever AI is used in assessments or tutoring,\naddressing the human-centered AI grand challenges identiﬁed\nby Ozmen Garibay et al. [183]. The University of California,\nBerkeley Center for Long-Term Cybersecurity provides guide-\nlines promoting data minimization, algorithmic accountability,\nand informed consent in the educational use of AI systems[184].\nIn K-12 education, New Y ork City Public Schools initially\nrestricted the use of generative AI tools, such as ChatGPT, to\nprotect student data, but later revised their policy to allow care-\nfully structured integration, contingent on teacher training and\nstrict data privacy protections[185]. The Massachusetts Institute\nof Technology Media Lab further advances ethical AI literacy\nby involving students in projects, such as the “Moral Machine,”\nencouraging critical reﬂection on AI decision-making processes\nand promoting student agency [186]. These cases illustrate how\nethical frameworks are operationalized in different educational\nsettings, offering practical models to protect student rights,\nensure fairness, and promote transparency in AGI applications\nin education.\nVIII. D ISCUSSION\nA. Summary of the Study\nThis article addresses the growing importance of understand-\ning how multimodal AGI can be integrated into educational\npractices. We ﬁrst reviewed the theoretical foundations of mul-\ntimodality in human learning, encompassing its concept and\nhistory, dual coding theory and multimedia theory, V ARK mul-\ntimodality, and multimodal assessment (see Section II-A). After\nthat, we revisited the essential components of AGI, particularly\nfocusing on the multimodal nature of AGI that distinguished\nitself from ANI. Based on its conversational functionality, mul-\ntimodal AGI is considered an educational agent already tested\nin various educational situations (see Section II-B). How sig-\nniﬁcant text, image, audio, and video modalities are for ed-\nucation, the technological backgrounds of AGI for analyzing\nand generating them, and educational applications of AI for\neach modality were thoroughly reviewed (see Sections III–VI).\nFinally, we comprehensively investigated the ethics of AGI in\neducation, originating from the ethics of AI and speciﬁed in three\nstrands—1) data privacy and ethical integrity, 2) explainability,\ntransparency, and fairness, and 3) responsibility and decision-\nmaking. Practical implementation of ethical AGI frameworks\nin education was reviewed (see Section VII) (see Figs. 1, 4,\nand 5).\nB. Implications for Learning Theories\nSimilar to information processing theory that analogized the\nhuman mind to computer [3], juxtaposing multimodality in\nhuman learning and the evolution of multimodal AGI provides\nbidirectional implications between the natures of human and\nmachine intelligence [57]. First, unveiling human cognitive pro-\ncesses provides a multimodal framework for AGI, underscoring\nthe need to mimic human cognitive processes for effective AGI\nsystems. We observe a prominent series of AI models, such as\nGPT, expanding its modality from text (GPT-3.5 and GPT-4)\nto incorporating image (GPT-4V) and audio (ChatGPT mobile\napp). This is not coincidental, but is the result of the effort of\nits developers to achieve multimodality [187]. Further efforts\nare needed to explore the implications of multimodal learning\ntheories on the development of multimodal AGI. Conversely,\nexamining AGI’s inner models and their performances in var-\nious settings enhances our understanding of student learning.\nFor example, testing the structural and functional principles of\nmultimodal AGI could provide us with potential knowledge of\nhuman multimodal cognition. Therefore, we highlight the need\nfor AGI-driven systems to model the human mind, a perspective\nthat enhances understanding of AGI’s potential in educational\nsettings, which in turn will contribute to knowledge generation\nin classrooms.\nC. Derived Operational Design Principles of Multimodal\nAgents\nBased on insights from the literature and our review, we\npropose design principles for developers and instructors that\ntranslate multimodal learning theory and AI ethics into action-\nable guidelines for creating multimodal agents. According to the\nCognitive Theory of Multimedia Learning [3], agents should\nregulate or integrate modalities to ensure that simultaneous\ninputs engage complementary channels, rather than compete\nfor the same working memory resources. For example, when\na diagram is presented, auto-generated verbal scaffolds should\nhighlight relational information not visually evident, rather than\nredundantly describing shapes.\nInstead of directly delivering feedback from the agent to stu-\ndents, the agent should generate draft scaffolds that are audited\nby teachers before reaching the learner. This teacher-in-the-loop\napproach may improve teacher acceptance [90]. These editable\nscaffolds could also be shared as open educational resources,\nfostering community-based support.\nData minimalism must be a core design principle, as mandated\nby the General Data Protection Regulation of the European\nUnion and similar statutes. Multimodal agents should collect\nsensitive data streams, such as facial video or ambient audio,\nonly when there is a clear pedagogical rationale. Also, the\nnecessary features (e.g., facial action units) should be extracted\nlocally, and raw data should be deleted on-device to minimize\nthe risk of data breaches.\nD. Current Research Gaps\nWe identiﬁed gaps in the current literature relevant to multi-\nmodal AGI in education. First, empirical studies on the impact of\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\n678 IEEE TRANSACTIONS ON LEARNING TECHNOLOGIES, VOL. 18, 2025\nFig. 6. Modality conversion in AGI system for education (black arrow:\nCurrently available; blue arrow: Future directions).\nmultimodal AGI in authentic teaching and learning situations are\nscarce. Most empirical studies on multimodal AGI in education\nreported until now were posthoc, such as training prediction\nmodels for already collected data (e.g., [4], [59], and [105]).\nFor example, Lee and Zhai [105] analyzed 900 student-drawn\nimages; they reported that the automatic scoring accuracy based\non GPT-4V (51% ) falls behind that of ResNet-50 V2 CNNs\npreviously trained for the task (79% –89% ), limiting its current\napplicability. Furthermore, intervention studies for empirical\nevidence of the effectiveness of AGI in education have not been\naccumulated much. A notable exception is Zheng et al. [188],\nwhich showed via a quasi-experimental study that the QWen\nAGI was effective in fostering eighth-grade students’ higher or-\nder thinking and self-efﬁcacy in a project-based learning context.\nHowever, the study did not focus much on multimodal learning.\nSecond, most AGI systems embrace two modes of text, im-\nage, audio, or video, not more than three. For example, as of\nnow, VLMs (e.g., GPT-4V and Gemini) are the most promi-\nnent multimodal AGI services for education with their VQA\ncapabilities ( [57]; see Sections IV -B2 and IV -C2). However,\nother multimodal models support text-to-image (e.g., DALL ·\nE, Imagen, Stable Diffusion), text-to-audio (e.g., Alexa, Siri,\nBixby, ChatGPT), and text-to-video (e.g., Sora, Movie Gen)\nconversions (see Fig. 6). Note that text has been the basis\nmodality for image, audio, and video analysis and generation,\nas reviewed above. The progression from text to video reﬂects\nthe increasing complexity and feasibility of AI applications\nacross these modalities. However, conversion from and to other\nvarious modalities is not prominent in the current status of\neducational AGI. Remarkably, in their quasi-experimental study,\nTracy and Spantidi [189] showed that a GPT-empowered AI\ninstructor agent in a virtual reality learning environment for\nbubble sort algorithm signiﬁcantly impacts learners’ higher\nengagement, conceptual knowledge transfer, and low intrinsic\ncognitive loads. Although the learning environment supported\nmultimodal learning (visual and kinesthetic), AGI was only used\nfor text generation rather than other modalities.\nE. Practical Constraints and Institutional Readiness\nWhile the affordances of multimodal AGI in education are\npromising, it is critical to acknowledge and address the practical\ntechnological constraints that educational institutions may face.\nDeploying AGI systems—especially those with multimodal\ncapabilities—requires substantial computational resources, such\nas high-performance GPUs or cloud-based infrastructure, which\nmay not be readily available in underfunded schools or ru-\nral regions. Moreover, the scalability of such systems poses\nchallenges: real-time multimodal processing can quickly strain\nbandwidth and local device capabilities, limiting accessibility\nin low-resource environments. Institutional readiness is another\nimportant consideration; integrating AGI necessitates technical\nsupport, infrastructure upgrades, and teacher training, all of\nwhich incur ﬁnancial and operational costs. While large-scale\ncloud platforms (e.g., Azure OpenAI, Google Cloud, and AWS\nBedrock) offer scalable deployment, the ongoing subscription or\nAPI call costs may limit widespread adoption. Future research\nand development should thus investigate cost-effective, edge-\nbased deployment models, open-source alternatives, or hybrid\nconﬁgurations that reduce dependence on centralized resources\nwhile maintaining performance. A more equitable path forward\nwill require both innovation in model optimization and support-\nive policy frameworks for educational technology funding.\nF . Future Directions\nIn response to the challenges associated with the use of AGI\nin multimodal learning, we indicate future research directions.\nThe ﬁrst key challenge is how to effectively scale AGI\nfor diverse educational contexts to deliver personalized mul-\ntimodal learning experiences. Intervention studies, especially\nquasi-experimental studies, should be further conducted and\nreported to estimate the instructional effect of multimodal learn-\ning supported by AGI. One future research topic is to develop,\nimplement, and evaluate a real-time feedback system based on\nVLM. For example, automatic assessment pipeline of student\ndrawings on the particulate nature of matter explainable in\nlight of the written scoring rubric [90] could be embedded in\na personalized learning device for classroom usage. How the\nsystem facilitates student learning could be investigated through\ndevice usage log, pretest and posttest, and qualitative interview,\ncompared to a control group. A large-scale empirical study and\na meta-analysis of accumulated reports are also future research\nagendas. These will help us foresee the future of teaching and\nlearning and the extent to which we could consult an educational\nmultimodal AGI agent.\nSecond, multimodal AGI for education should evolve to in-\ncorporate more than two modalities, and does not need to start\nfrom text modality (Fig. 6; see Section VIII-D). Looking ahead,\nit is suggested that a move toward personalized learning assis-\ntants capable of analyzing and responding to student-generated\nmultimodal data offers individualized support. For example,\nstudents’ kinesthetic movements in physical education or lab-\nbased learning situations could be fed to AGI as video data to\ngenerate feedback for the learners and instructional cues for\nteachers. This trajectory highlights the transformation of AGI\nfrom a supplemental tool in text-based education to a central,\nmultifunctional agent within the educational ecosystem.\nEven if future studies are successful in addressing these two\nagendas, we again stress that the affordances of and ethical\nAuthorized licensed use limited to: Central China Normal University. Downloaded on October 30,2025 at 12:25:03 UTC from IEEE Xplore. Restrictions apply.\n\nLEE et al.: MULTIMODALITY OF AI FOR EDUCA TION: TOW ARD ARTIFICIAL GENERAL INTELLIGENCE 679\nconsiderations in using multimodal AGI for education are in-\ntertwined. The ethical considerations (see Section VII) safe-\nguard the participants, processes, and outcomes of educational\npractices rather than impose regulatory burdens. Thus, future\nresearch should frame the ethical use of AGI in education to\nensure the safety and well-being of students and teachers. We\nadvocate for the protection of physiological, psychological, and\ncognitive safety when AGI is employed for education. This\naligns with the broader concept of “safe AI” for human well-\nbeing, which emphasizes sensitivity, evaluation, user-centric\ndesign, responsibility, beneﬁcence, and security features in the\nhealthcare ﬁeld [190]. By collectively embracing the ethical\nconsiderations, the potential beneﬁts of integrating multimodal\nAGI into education can be fully realized in the future.\nFinally, future studies should explore multimodal AGI’s po-\ntential to not only support individualized learning but also\nenhance collaborative learning environments. In such an en-\nvironment, learners and multimodal AGI agents collaborate\nunder human instructor’s arbitration [116]. By balancing the\nabovementioned factors, AGI could be harnessed to foster more\ninnovative and inclusive educational practices.\nIX. C ONCLUSION\nThis article explored the pivotal role of multimodality in\nsteering the progress toward AGI in educational contexts. Our\ninvestigation underscored the integration of diverse cognitive\nchannels, highlighting how multimodal AI complements and en-\nhances human learners’ educational experience. This integration\nfacilitates a more comprehensive, inclusive, and effective learn-\ning process, accommodating various learning styles and needs.\nThe transformative potential of AGI in education is profound.\nEspecially, the recent release of OpenAI’s o1 [191] showcased\na giant step toward the realization of AGI, which is capable of\ncomplex reasoning tasks in the educational ﬁeld [192].A G I ’ s\ncapabilities in providing personalized, dynamic, and interactive\nlearning experiences promise to revolutionize educational meth-\nods, making them more adaptive and responsive to individual\nlearner’s requirements.\nOur ﬁndings emphasize the necessity of continued research.\nIt calls for collaborative efforts from educators, researchers,\ntechnologists, and policymakers. The impact of AGI in reshap-\ning educational landscapes holds the promise of a future where\neducation is more accessible, engaging, and effective for every\nlearner. Thus, our exploration of the multimodal dimensions\nof AGI for education sets a foundational framework for future\ndevelopments in this rapidly evolving ﬁeld.\nACKNOWLEDGMENT\nThe opinions expressed are those of the authors and do\nnot represent views of the Institute or the U.S. Department of\nEducation.\nREFERENCES\n[1] OpenAI, “GPT-4 technical report,” 2023, arXiv:2303.08774. [Online].\nAvailable: https://api.semanticscholar.org/CorpusID:257532815\n[2] G. Gemini Team, “Gemini: A family of highly capable multimodal\nmodels,” 2023. [Online]. Available: https://storage.googleapis.com/\ndeepmind-media/gemini/gemini_1_report.pdf\n[3] R. Mayer and V . Sims, “For whom is a picture worth a thousand words?\nExtensions of a d