-- ----------------------------
-- Table structure for teaching_resource
-- ----------------------------
DROP TABLE IF EXISTS `teaching_resource`;
CREATE TABLE `teaching_resource`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `job_id` bigint UNSIGNED NOT NULL,
  `project_id` bigint UNSIGNED NOT NULL,
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `settings_json` json NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'READY',
  `current_version_no` int UNSIGNED NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_teaching_resource_job_type`(`job_id` ASC, `resource_type` ASC) USING BTREE,
  INDEX `idx_teaching_resource_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_teaching_resource_job`(`job_id` ASC) USING BTREE,
  INDEX `idx_teaching_resource_project_type`(`project_id` ASC, `resource_type` ASC) USING BTREE,
  CONSTRAINT `fk_teaching_resource_job` FOREIGN KEY (`job_id`) REFERENCES `resource_creation_job` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_teaching_resource_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_teaching_resource_type` CHECK (`resource_type` in (_utf8mb4'PPT',_utf8mb4'TEACHER_GUIDE',_utf8mb4'WORKSHEET',_utf8mb4'TASK_CARD',_utf8mb4'AI_CASE',_utf8mb4'DISCUSSION',_utf8mb4'ASSESSMENT',_utf8mb4'REFLECTION'))
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

