-- Records of teaching_resource
-- ----------------------------

-- ----------------------------
-- Table structure for teaching_resource_version
-- ----------------------------
DROP TABLE IF EXISTS `teaching_resource_version`;
CREATE TABLE `teaching_resource_version`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `resource_id` bigint UNSIGNED NOT NULL,
  `version_no` int UNSIGNED NOT NULL,
  `content_json` json NOT NULL,
  `content_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `change_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `change_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_by` bigint UNSIGNED NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_teaching_resource_version`(`resource_id` ASC, `version_no` ASC) USING BTREE,
  INDEX `fk_teaching_resource_version_created_by`(`created_by` ASC) USING BTREE,
  INDEX `idx_teaching_resource_version_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_teaching_resource_version_resource_no`(`resource_id` ASC, `version_no` ASC) USING BTREE,
  CONSTRAINT `fk_teaching_resource_version_created_by` FOREIGN KEY (`created_by`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_teaching_resource_version_resource` FOREIGN KEY (`resource_id`) REFERENCES `teaching_resource` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_teaching_resource_version_source` CHECK (`change_source` in (_gbk'AI',_gbk'TEACHER',_gbk'AI_ACCEPTED'))
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

